const rtdal005894Source0001 = "use_rlang_c_library <- function() {\n  check_installed(c(\"fs\", \"usethis\"), \"to install the rlang C library.\")\n\n  rlang_path <- Sys.getenv(\"RLANG_PATH\")\n  if (!nzchar(rlang_path)) {\n    rlang_path <- download_rlang()\n    on.exit(fs::dir_delete(rlang_path))\n  }\n\n  check_rlang(rlang_path)\n  rlang_lib_path <- fs::path(rlang_path, \"src\", \"rlang\")\n  rlang_lib_include_path <- fs::path(rlang_path, \"src\", \"rlang.c\")\n\n  proj_path <- usethis::proj_get()\n  if (is_rlang_dir(proj_path)) {\n    abort(c(\n      \"Can't update rlang from itself.\",\n      i = \"Did you forget to change project?\"\n    ))\n  }\n\n  src_path <- fs::path(proj_path, \"src\")\n  lib_path <- fs::path(src_path, \"rlang\")\n  lib_include_path <- fs::path(src_path, \"rlang.c\")\n\n  has_library <- any(fs::file_exists(c(lib_path, lib_include_path)))\n\n  if (has_library) {\n    no_prompt <- tolower(Sys.getenv(\"RLANG_LIB_NO_PROMPT\"))\n    if (!is_string(no_prompt, \"true\")) {\n      prompt <- paste(\"Remove existing library in\", src_path)\n      if (!usethis::ui_yeah(prompt)) {\n        invokeRestart(\"abort\")\n      }\n    }\n\n    if (fs::file_exists(lib_path)) {\n      fs::file_delete(lib_path)\n    }\n    if (any(fs::file_exists(lib_include_path))) {\n      fs::file_delete(lib_include_path)\n    }\n  }\n\n  fs::dir_copy(rlang_lib_path, lib_path)\n  fs::file_copy(rlang_lib_include_path, lib_include_path)\n\n  if (has_library) {\n    usethis::ui_done(\"Updated rlang library.\")\n  } else {\n    usethis::ui_done(\"Installed rlang library to `src/rlang`.\")\n  }\n\n  if (!has_include_directive(src_path)) {\n    usethis::ui_todo(\"Add to `src/Makevars`:\")\n    usethis::ui_code_block(\"PKG_CPPFLAGS = -I./rlang\")\n  }\n  if (!detect_rlang_lib_usage(src_path)) {\n    usethis::ui_todo(\"Include the library with `#include <rlang.h>`.\")\n    usethis::ui_todo(\"Call `r_init_library()` from your `.onLoad()` hook.\")\n  }\n}"

const rtdal005894Source0002 = `download_rlang <- function() {
  dest_zip <- fs::file_temp("rlang-src")

  url <- "https://github.com/r-lib/rlang/archive/main.zip"
  utils::download.file(url, dest_zip)

  dest_dir <- fs::file_temp("rlang-src")
  utils::unzip(dest_zip, exdir = dest_dir)

  fs::path(dest_dir, "rlang-main")
}`

const rtdal005894Source0003 = `check_rlang <- function(path) {
  if (!is_rlang_dir(path)) {
    abort("Can't find rlang in path.")
  }
}`

const rtdal005894Source0004 = `is_rlang_dir <- function(path) {
  lib_path <- fs::path(path, "src", "rlang")
  desc_path <- fs::path(path, "DESCRIPTION")

  if (!fs::dir_exists(lib_path)) {
    return(FALSE)
  }
  if (!fs::file_exists(desc_path)) {
    return(FALSE)
  }

  desc <- readLines(desc_path, n = 1)
  if (!is_string(desc, "Package: rlang")) {
    return(FALSE)
  }

  TRUE
}`

const rtdal005894Source0005 = `has_include_directive <- function(src_path) {
  makevars_path <- fs::path(src_path, "Makevars")

  if (!fs::file_exists(makevars_path)) {
    return(FALSE)
  }

  makevars_lines <- readLines(makevars_path)
  any(grepl("PKG_CPPFLAGS.*-I.*rlang", makevars_lines))
}`

const rtdal005894Source0006 = `detect_rlang_lib_usage <- function(src_path) {
  src_files <- fs::dir_ls(src_path, glob = "*.c", recurse = TRUE)
  src_files <- src_files[!grepl("/src/rlang/", src_files)]

  has_include <- FALSE
  has_init <- FALSE

  for (file in src_files) {
    lines <- readLines(file)

    if (any(grepl("#include <rlang.h>", lines))) {
      has_include <- TRUE
    }
    if (any(grepl("r_init_library", lines))) {
      has_init <- TRUE
    }

    if (has_include && has_init) {
      return(TRUE)
    }
  }

  FALSE
}`

const rtdal005894Source0020 = `print.rlang_dict <- function(x, ...) {
  writeLines(sprintf("<rlang/dict: %s>", obj_address(x)))
  writeLines(paste0("size: ", dict_size(x)))
}`

const rtdal005894Source0055 = `print.rlang_dyn_array <- function(x, ...) {
  writeLines(sprintf("<rlang/dyn_array: %s>", obj_address(x)))

  info <- dyn_info(x)
  writeLines(paste0("count: ", info$count))
  writeLines(paste0("capacity: ", info$capacity))
  writeLines(paste0("growth_factor: ", info$growth_factor))
  writeLines(paste0("type: ", info$type))
  writeLines(paste0("elt_byte_size: ", info$elt_byte_size))
}`

