const rtdal005895Source0001 = `call2 <- function(.fn, ..., .ns = NULL) {
  .External2(ffi_call2, .fn, .ns)
}`

const rtdal005895Source0002 = `pairlist2 <- function(...) {
  .Call(
    ffi_dots_pairlist,
    frame_env = environment(),
    named = FALSE,
    ignore_empty = "trailing",
    preserve_empty = TRUE,
    unquote_names = TRUE,
    homonyms = "keep",
    check_assign = FALSE
  )
}`

const rtdal005895Source0005 = `is_call2 <- function(x, ...) {
  if (is_quosure(x)) {
    FALSE
  } else {
    rlang::is_call(x, ...)
  }
}`

const rtdal005895Source0007 = "call_print_fine_type <- function(call) {\n  check_call(call)\n\n  op <- call_parse_type(call)\n  if (op == \"\") {\n    return(\"call\")\n  }\n\n  switch(\n    op,\n    `+unary` = ,\n    `-unary` = ,\n    `~unary` = ,\n    `?unary` = ,\n    `!` = ,\n    `!!` = ,\n    `!!!` = \"prefix\",\n    `function` = ,\n    `while` = ,\n    `for` = ,\n    `repeat` = ,\n    `if` = \"control\",\n    `(` = ,\n    `{{` = ,\n    `{` = \"delim\",\n    `[` = ,\n    `[[` = \"subset\",\n    # These operators always print in infix form even if they have\n    # more arguments\n    `<-` = ,\n    `<<-` = ,\n    `=` = ,\n    `::` = ,\n    `:::` = ,\n    `$` = ,\n    `@` = \"infix\",\n    `+` = ,\n    `-` = ,\n    `?` = ,\n    `~` = ,\n    `:=` = ,\n    `|` = ,\n    `||` = ,\n    `&` = ,\n    `&&` = ,\n    `>` = ,\n    `>=` = ,\n    `<` = ,\n    `<=` = ,\n    `==` = ,\n    `!=` = ,\n    `*` = ,\n    `/` = ,\n    `%%` = ,\n    `special` = ,\n    `:` = ,\n    `^` = if (length(node_cdr(call)) == 2) {\n      \"infix\"\n    } else {\n      \"call\"\n    }\n  )\n}"

const rtdal005895Source0011 = "call_modify <- function(\n  .call,\n  ...,\n  .homonyms = c(\"keep\", \"first\", \"last\", \"error\"),\n  .standardise = NULL,\n  .env = caller_env()\n) {\n  args <- dots_list(..., .preserve_empty = TRUE, .homonyms = .homonyms)\n\n  expr <- get_expr(.call)\n  check_call(expr, arg = \".call\")\n\n  expr <- duplicate(expr, shallow = TRUE)\n\n  # Discard \"\" names\n  nms <- names2(args)\n  named <- have_name(args)\n  named_args <- args[named]\n\n  for (i in seq_along(args)) {\n    tag <- sym(nms[[i]])\n    arg <- args[[i]]\n\n    if (is_missing(tag)) {\n      if (is_zap(arg)) {\n        abort(\"Zap sentinels can't be unnamed\")\n      }\n      node_append(expr, new_node(arg))\n      next\n    }\n\n    if (identical(tag, dots_sym)) {\n      # Unwrap empty quosures. Useful for passing captured arguments\n      # to `call_modify()`.\n      if (identical(maybe_missing(arg), quo())) {\n        arg <- missing_arg()\n      }\n      if (!is_missing(arg) && !is_zap(arg)) {\n        abort(\"`...` arguments must be `zap()` or empty\")\n      }\n      node_accessor <- node_car\n    } else {\n      node_accessor <- node_tag\n    }\n\n    prev <- expr\n    node <- node_cdr(expr)\n\n    while (!is_null(node)) {\n      if (identical(node_accessor(node), tag)) {\n        # Remove argument from the list if a zap sentinel\n        if (is_zap(maybe_missing(arg))) {\n          node <- node_cdr(node)\n          node_poke_cdr(prev, node)\n          next\n        }\n\n        # If `...` it can only be missing at this point, which means\n        # we keep it in the argument list as is\n        if (!identical(tag, dots_sym)) {\n          node_poke_car(node, maybe_missing(arg))\n        }\n\n        break\n      }\n\n      prev <- node\n      node <- node_cdr(node)\n    }\n\n    if (is_null(node) && !is_zap(maybe_missing(arg))) {\n      if (identical(tag, dots_sym)) {\n        node <- new_node(dots_sym, NULL)\n        node_poke_cdr(prev, node)\n      } else {\n        node <- new_node(maybe_missing(arg), NULL)\n        node_poke_tag(node, tag)\n        node_poke_cdr(prev, node)\n      }\n    }\n  }\n\n  set_expr(.call, expr)\n}"

const rtdal005895Source0014 = "call_match <- function(\n  call = NULL,\n  fn = NULL,\n  ...,\n  defaults = FALSE,\n  dots_env = NULL,\n  dots_expand = TRUE\n) {\n  check_dots_empty0(...)\n\n  if (is_null(call)) {\n    call <- sys.call(sys.parent())\n    fn <- fn %||% sys.function(sys.parent())\n    dots_env <- dots_env %||% caller_env(2)\n  } else {\n    dots_env <- dots_env %||% env(empty_env(), ... = NULL)\n  }\n\n  if (is_null(fn)) {\n    abort(\"`fn` must be supplied.\")\n  }\n  if (!is_environment(dots_env)) {\n    abort(\"`dots_env` must be an environment.\")\n  }\n\n  if (is_primitive(fn)) {\n    return(call)\n  }\n\n  # Don't expand dots before matching defaults to make it easier to\n  # sort the arguments by formals\n  call <- match.call(fn, call, expand.dots = FALSE, envir = dots_env)\n\n  if (defaults) {\n    fmls <- fn_fmls(fn)\n    names <- names(fmls)\n    missing <- !names %in% names(call)\n\n    args <- c(as.list(call[-1]), fmls[missing])\n    args <- args[names]\n    call <- call2(call[[1]], !!!args)\n  }\n\n  if (is_missing(call$...)) {\n    call$... <- NULL\n    return(call)\n  }\n\n  if (!dots_expand) {\n    return(call)\n  }\n\n  i <- match(\"...\", names(call))\n  if (is_na(i)) {\n    return(call)\n  }\n\n  call <- as.list(call)\n  as.call(c(\n    call[seq2(1, i - 1)],\n    call$...,\n    call[seq2(i + 1, length(call))]\n  ))\n}"

const rtdal005895Source0016 = `call_ns <- function(call) {
  check_required(call)

  if (is_quosure(call) || is_formula(call)) {
    call <- get_expr(call)
  }
  check_call(call)

  if (!is_call(call)) {
    abort_call_input_type("call")
  }

  head <- call[[1]]
  if (is_call(head, c("::", ":::"))) {
    as_string(head[[2]])
  } else {
    NULL
  }
}`

const rtdal005895Source0018 = `is_call_index <- function(x, ns = NULL) {
  check_required(x)

  if (!is_call(x)) {
    return(FALSE)
  }

  out <- FALSE

  while (is_call(fn <- x[[1]])) {
    if (!is_call(fn, c("$", "@", "[", "[["))) {
      return(FALSE)
    }

    if (!every(fn[-1], is_arg_index, ns)) {
      return(FALSE)
    }

    out <- TRUE
    x <- fn
  }

  out
}`

const rtdal005895Source0024 = `call_unnamespace <- function(x) {
  if (is_namespaced_call(x)) {
    call <- call2(node_cadr(node_cdar(x)))
    node_poke_cdr(call, node_cdr(x))
  } else {
    x
  }
}`

const rtdal005895Source0026 = `is_namespaced_symbol <- function(x, ns = NULL, private = NULL) {
  if (typeof(x) != "language") {
    return(FALSE)
  }
  if (!is_null(ns) && !identical(node_cadr(x), sym(ns))) {
    return(FALSE)
  }

  head <- node_car(x)
  if (is_null(private)) {
    identical(head, namespace_sym) || identical(head, namespace2_sym)
  } else if (private) {
    identical(head, namespace2_sym)
  } else {
    identical(head, namespace_sym)
  }
}`

const rtdal005895Source0027 = `call_type <- function(x) {
  x <- get_expr(x)
  stopifnot(typeof(x) == "language")

  type <- typeof(node_car(x))
  if (type == "symbol") {
    "named"
  } else if (is_namespaced_symbol(node_car(x))) {
    "namespaced"
  } else if (type == "language") {
    "recursive"
  } else if (type %in% c("closure", "builtin", "special")) {
    "inlined"
  } else {
    abort("corrupt language object")
  }
}`

