const rtdal005897Source0004 = `environment(hnd_entrace) <- baseenv()`

const rtdal005897Source0005 = "entrace <- function(cnd, ..., top = NULL, bottom = NULL) {\n  check_dots_empty0(...)\n\n  if (!missing(cnd) && inherits(cnd, \"rlang_error\")) {\n    poke_last_error(cnd)\n    return()\n  }\n\n  if (is_null(bottom)) {\n    if (missing(cnd)) {\n      bottom <- current_env()\n    } else {\n      bottom <- caller_env()\n    }\n  }\n\n  # Remove handler invocation context from the trace\n  if (is_environment(bottom)) {\n    nframe <- eval_bare(quote(base::sys.nframe()), bottom) - 1\n    info <- signal_context_info(nframe)\n    bottom <- sys.frame(info[[2]])\n  }\n\n  if (!has_new_cmd_frame() && the$n_conditions >= max_entracing()) {\n    trace <- NULL\n  } else {\n    trace <- trace_back(top = top, bottom = bottom)\n  }\n\n  # `options(error = )` case\n  if (missing(cnd)) {\n    return(entrace_handle_top(trace))\n  }\n\n  # Log warnings\n  if (is_warning(cnd)) {\n    wrn <- as_rlang_warning(cnd, trace)\n    push_warning(wrn)\n\n    # Resignal enriched warning\n    if (!is_null(findRestart(\"muffleWarning\"))) {\n      if (identical(peek_option(\"warn\"), 2L)) {\n        return()\n      } else {\n        warning(wrn)\n        invokeRestart(\"muffleWarning\")\n      }\n    } else {\n      return()\n    }\n  }\n\n  # Log messages\n  if (is_message(cnd)) {\n    push_message(as_rlang_message(cnd, trace))\n    return()\n  }\n\n  # Rethrow errors\n  if (is_error(cnd)) {\n    if (has_recover()) {\n      return()\n    }\n    entraced <- error_cnd(\n      message = conditionMessage(cnd) %||% \"\",\n      call = conditionCall(cnd),\n      error = cnd,\n      trace = trace,\n      use_cli_format = FALSE\n    )\n    poke_last_error(entraced)\n    cnd_signal(entraced)\n  }\n\n  # Ignore other condition types\n  NULL\n}"

const rtdal005897Source0008 = `cnd_entrace <- function(cnd, ..., top = NULL, bottom = NULL) {
  check_dots_empty0(...)

  if (cnd_some(cnd, function(x) !is_null(x[["trace"]]))) {
    return(cnd)
  }

  if (is_null(bottom)) {
    nframe <- sys.parent() - 1
    info <- signal_context_info(nframe)
    bottom <- sys.frame(info[[2]])
  }
  cnd$trace <- trace_back(top = top, bottom = bottom)

  cnd
}`

