const rtdal005901Source0001 = `cnd_signal <- function(cnd, ...) {
  check_dots_empty0(...)

  .__signal_frame__. <- TRUE

  if (is_null(cnd)) {
    return(invisible(NULL))
  }

  switch(
    cnd_type(cnd),
    error = {
      if (is_environment(cnd$call)) {
        frame <- cnd$call
        cnd$call <- error_call(cnd$call)
      } else {
        frame <- caller_env()
      }
      if (is_null(cnd$trace)) {
        info <- abort_context(frame, rethrowing = !is_null(cnd$parent))
        with_options(
          "rlang:::visible_bottom" = info$bottom_frame,
          {
            cnd$trace <- trace_back()
          }
        )
      }
      signal_abort(cnd)
    },
    warning = warning(cnd),
    message = message(cnd),
    interrupt = interrupt(),
    condition = invisible(withRestarts(
      rlang_muffle = function() NULL,
      signalCondition(cnd)
    ))
  )
}`

const rtdal005901Source0002 = "warn <- function(\n  message = NULL,\n  class = NULL,\n  ...,\n  body = NULL,\n  footer = NULL,\n  parent = NULL,\n  use_cli_format = NULL,\n  .inherit = NULL,\n  .frequency = c(\"always\", \"regularly\", \"once\"),\n  .frequency_id = NULL,\n  .subclass = deprecated()\n) {\n  message <- validate_signal_args(message, class, NULL, .subclass, \"warn\")\n\n  message_info <- cnd_message_info(\n    message,\n    body,\n    footer,\n    caller_env(),\n    use_cli_format = use_cli_format\n  )\n  message <- message_info$message\n  extra_fields <- message_info$extra_fields\n  use_cli_format <- message_info$use_cli_format\n\n  .frequency <- arg_match0(.frequency, c(\"always\", \"regularly\", \"once\"))\n  if (\n    !needs_signal(\n      .frequency,\n      .frequency_id,\n      warning_freq_env,\n      \"rlib_warning_verbosity\"\n    )\n  ) {\n    return(invisible(NULL))\n  }\n\n  if (!is_null(parent)) {\n    # Don't inherit from `parent` by default if chained to a\n    # downgraded error\n    if (is_null(.inherit)) {\n      .inherit <- !inherits(parent, \"error\")\n    }\n    extra_fields$rlang <- c(\n      extra_fields$rlang,\n      list(inherit = .inherit)\n    )\n  }\n\n  cnd <- warning_cnd(\n    class,\n    message = message,\n    !!!extra_fields,\n    use_cli_format = use_cli_format,\n    parent = parent,\n    ...\n  )\n  cnd$footer <- c(cnd$footer, message_freq(message, .frequency, \"warning\"))\n\n  local_long_messages()\n  warning(cnd)\n}"

const rtdal005901Source0003 = "inform <- function(\n  message = NULL,\n  class = NULL,\n  ...,\n  body = NULL,\n  footer = NULL,\n  parent = NULL,\n  use_cli_format = NULL,\n  .inherit = NULL,\n  .file = NULL,\n  .frequency = c(\"always\", \"regularly\", \"once\"),\n  .frequency_id = NULL,\n  .subclass = deprecated()\n) {\n  message <- message %||% \"\"\n\n  validate_signal_args(message, class, NULL, .subclass, \"inform\")\n\n  message_info <- cnd_message_info(\n    message,\n    body,\n    footer,\n    caller_env(),\n    use_cli_format = use_cli_format\n  )\n  message <- message_info$message\n  extra_fields <- message_info$extra_fields\n  use_cli_format <- message_info$use_cli_format\n\n  .frequency <- arg_match0(.frequency, c(\"always\", \"regularly\", \"once\"))\n  if (\n    !needs_signal(\n      .frequency,\n      .frequency_id,\n      message_freq_env,\n      \"rlib_message_verbosity\"\n    )\n  ) {\n    return(invisible(NULL))\n  }\n\n  if (!is_null(parent)) {\n    # Don't inherit from `parent` by default if chained to a\n    # downgraded warning or error\n    if (is_null(.inherit)) {\n      .inherit <- !inherits(parent, c(\"warning\", \"error\"))\n    }\n    extra_fields$rlang <- c(\n      extra_fields$rlang,\n      list(inherit = .inherit)\n    )\n  }\n\n  cnd <- message_cnd(\n    class,\n    message = message,\n    !!!extra_fields,\n    parent = parent,\n    use_cli_format = use_cli_format,\n    ...\n  )\n  cnd$footer <- c(cnd$footer, message_freq(message, .frequency, \"message\"))\n\n  withRestarts(muffleMessage = function() NULL, {\n    signalCondition(cnd)\n    msg <- paste0(conditionMessage(cnd), \"\\n\")\n    cat(msg, file = .file %||% default_message_file())\n  })\n\n  invisible()\n}"

const rtdal005901Source0004 = `signal <- function(message = "", class, ..., .subclass = deprecated()) {
  validate_signal_args(message, class, NULL, .subclass, "signal")

  message <- .rlang_cli_format_fallback(message)
  cnd <- cnd(class, ..., message = message)
  cnd_signal(cnd)
}`

const rtdal005901Source0005 = `local_long_messages <- function(..., frame = caller_env()) {
  if (peek_option("warning.length") == 1000) {
    local_options(warning.length = 8170, .frame = frame)
  }
}`

const rtdal005901Source0006 = `default_message_file <- function() {
  opt <- peek_option("rlang:::message_file")
  if (!is_null(opt)) {
    return(opt)
  }

  if (
    (is_interactive() || is_rstudio()) &&
      sink.number("output") == 0 &&
      sink.number("message") == 2
  ) {
    stdout()
  } else {
    stderr()
  }
}`

const rtdal005901Source0013 = "needs_signal <- function(frequency, id, env, opt) {\n  local_error_call(\"caller\")\n\n  switch(\n    peek_verbosity(opt),\n    verbose = return(TRUE),\n    quiet = return(FALSE),\n    default = NULL\n  )\n\n  if (is_string(frequency, \"always\")) {\n    return(TRUE)\n  }\n  # Safe to remove in 2022\n  if (is_true(peek_option(\"rlang:::message_always\"))) {\n    return(TRUE)\n  }\n\n  if (is_null(id)) {\n    abort(sprintf(\n      \"%s must be supplied with %s.\",\n      format_arg(\".frequency_id\"),\n      format_arg(\".frequency\")\n    ))\n  }\n  check_string(id, allow_empty = FALSE, arg = \".frequency\")\n\n  sentinel <- env[[id]]\n  if (is_null(sentinel)) {\n    env_poke(env, id, Sys.time())\n    return(TRUE)\n  }\n\n  if (is_string(frequency, \"once\")) {\n    return(FALSE)\n  }\n\n  if (!inherits(sentinel, \"POSIXct\")) {\n    abort(\"Expected `POSIXct` value.\", .internal = TRUE)\n  }\n\n  # Signal every 8 hours\n  (Sys.time() - sentinel) > (8 * 60 * 60)\n}"

