const rtdal005902Source0002 = "cnd <- function(class, ..., message = \"\", call = NULL, use_cli_format = NULL) {\n  check_required(class)\n\n  if (is_environment(call)) {\n    call <- error_call(call)\n  }\n\n  fields <- cnd_fields(\n    ...,\n    call = call,\n    `_use_cli_format` = use_cli_format,\n    `_fn` = \"cnd\",\n    `_frame` = caller_env()\n  )\n\n  .Call(ffi_new_condition, class, message, fields)\n}"

const rtdal005902Source0003 = "error_cnd <- function(\n  class = NULL,\n  ...,\n  message = \"\",\n  call = NULL,\n  trace = NULL,\n  parent = NULL,\n  use_cli_format = NULL\n) {\n  if (!is_null(trace) && !inherits(trace, \"rlang_trace\")) {\n    stop_input_type(trace, \"`NULL` or an rlang backtrace\")\n  }\n  if (!is_null(parent) && !inherits(parent, \"condition\")) {\n    stop_input_type(parent, \"`NULL` or a condition object\")\n  }\n\n  if (is_environment(call)) {\n    call <- error_call(call)\n  }\n\n  fields <- error_cnd_fields(\n    trace = trace,\n    parent = parent,\n    ...,\n    use_cli_format = use_cli_format,\n    call = call\n  )\n\n  .Call(\n    ffi_new_condition,\n    c(class, \"rlang_error\", \"error\"),\n    message,\n    fields\n  )\n}"

const rtdal005902Source0004 = "error_cnd_fields <- function(\n  trace,\n  parent,\n  ...,\n  use_cli_format = NULL,\n  .subclass = NULL,\n  `_env` = caller_env(),\n  `_frame` = caller_env(2)\n) {\n  if (!is_null(.subclass)) {\n    deprecate_subclass(.subclass, \"error_cnd\", `_env`)\n  }\n\n  use_cli_format <- use_cli_format %||% use_cli(`_frame`)[[\"format\"]]\n\n  if (is_true(use_cli_format)) {\n    list2(trace = trace, parent = parent, ..., use_cli_format = TRUE)\n  } else {\n    list2(trace = trace, parent = parent, ...)\n  }\n}"

const rtdal005902Source0005 = "warning_cnd <- function(\n  class = NULL,\n  ...,\n  message = \"\",\n  call = NULL,\n  use_cli_format = NULL\n) {\n  if (is_environment(call)) {\n    call <- error_call(call)\n  }\n\n  fields <- cnd_fields(\n    ...,\n    call = call,\n    `_use_cli_format` = use_cli_format,\n    `_fn` = \"warning_cnd\",\n    `_frame` = caller_env()\n  )\n\n  .Call(\n    ffi_new_condition,\n    c(class, \"rlang_warning\", \"warning\"),\n    message,\n    fields\n  )\n}"

