const rtdal005903Source0026 = `parens_deparse <- function(x, lines = new_lines()) {
  lines$push("(")
  lines$deparse(node_cadr(x))
  lines$push(")")

  lines$get_lines()
}`

const rtdal005903Source0027 = `braces_deparse <- function(x, lines = new_lines()) {
  lines$push("{")
  lines$increase_indent()

  x <- node_cdr(x)

  # No need for a newline if the block is empty
  if (is_null(x)) {
    lines$push(" }")
    return(lines$get_lines())
  }

  while (!is_null(x)) {
    lines$push_newline()
    lines$deparse(node_car(x))
    x <- node_cdr(x)
  }

  lines$decrease_indent()
  lines$push_newline()
  lines$push("}")

  lines$get_lines()
}`

const rtdal005903Source0028 = `embrace_deparse <- function(x, lines = new_lines()) {
  lines$push("{{ ")
  lines$increase_indent()

  sym <- node_cadr(node_cadr(x))
  lines$deparse(sym)

  lines$push(" }}")
  lines$decrease_indent()

  lines$get_lines()
}`

const rtdal005903Source0029 = "sym_deparse <- function(x, lines = new_lines()) {\n  str <- encodeString(as_string(x))\n\n  if (needs_backticks(str)) {\n    str <- sprintf(\"`%s`\", str)\n  }\n\n  lines$push(str)$get_lines()\n}"

const rtdal005903Source0030 = `args_deparse <- function(x, lines = new_lines(), delims = c("(", ")")) {
  stopifnot(is_character(delims, n = 2))

  lines$push_sticky(delims[[1]])
  lines$increase_indent()

  while (!is_null(x)) {
    tag <- node_tag(x)
    if (!is_null(tag)) {
      sym_deparse(tag, lines = lines)
      lines$push_sticky(" = ")
      lines$make_next_sticky()
    }
    lines$deparse(node_car(x))

    x <- node_cdr(x)
    if (!is_null(x)) {
      lines$push_sticky(", ")
    }
  }

  lines$push_sticky(delims[[2]])
  lines$decrease_indent()

  lines$get_lines()
}`

const rtdal005903Source0031 = `call_deparse <- function(x, lines = new_lines()) {
  car <- node_car(x)

  type <- call_delimited_type(car)
  switch(
    type,
    parens = {
      car <- call("(", car)
      lines$deparse(car)
    },
    backticks = {
      lines$deparse(node_car(car))
      args_deparse(node_cdr(car), lines)
    },
    lines$deparse(car)
  )

  args_deparse(node_cdr(x), lines)
}`

const rtdal005903Source0033 = "op_deparse <- function(op, x, lines) {\n  deparser <- switch(\n    op,\n    `function` = fn_call_deparse,\n    `while` = while_deparse,\n    `for` = for_deparse,\n    `repeat` = repeat_deparse,\n    `if` = if_deparse,\n    `next` = next_deparse,\n    `break` = break_deparse,\n    `?` = ,\n    `<-` = ,\n    `<<-` = ,\n    `=` = ,\n    `:=` = ,\n    `~` = ,\n    `|` = ,\n    `||` = ,\n    `&` = ,\n    `&&` = ,\n    `>` = ,\n    `>=` = ,\n    `<` = ,\n    `<=` = ,\n    `==` = ,\n    `!=` = ,\n    `+` = ,\n    `-` = ,\n    `*` = ,\n    `/` = ,\n    `%%` = ,\n    `special` = spaced_op_deparse,\n    `:` = ,\n    `^` = ,\n    `$` = ,\n    `@` = unspaced_op_deparse,\n    `::` = ,\n    `:::` = tight_op_deparse,\n    `~unary` = unary_f_deparse,\n    `?unary` = ,\n    `!` = ,\n    `!!!` = ,\n    `!!` = ,\n    `+unary` = ,\n    `-unary` = unary_op_deparse,\n    `[` = brackets_deparse,\n    `[[` = brackets2_deparse,\n    `(` = parens_deparse,\n    `{` = braces_deparse,\n    `{{` = embrace_deparse,\n    abort(\"Internal error: Unexpected operator while deparsing\")\n  )\n\n  deparser(x, lines)\n  lines$get_lines()\n}"

const rtdal005903Source0034 = `call_deparser <- function(x) {
  op <- call_parse_type(x)
  if (op != "") {
    function(x, lines) op_deparse(op, x, lines)
  } else {
    call_deparse
  }
}`

const rtdal005903Source0037 = `atom_deparse <- function(x, lines = new_lines()) {
  if (is_scalar_deparsable(x)) {
    lines$push(deparse(x))
    return(NULL)
  }

  max_elements <- lines$max_elements

  truncated <- !is.null(max_elements) && length(x) > max_elements
  if (truncated) {
    x <- .subset(x, seq_len(max_elements))
  }

  lines$push(paste0("<", rlang_type_sum(x), ": "))
  lines$increase_indent()

  elts <- atom_elements(x)
  nms <- deparsed_names(x)

  n <- length(elts)
  for (i in seq_len(n)) {
    nm <- nms[[i]]
    if (nzchar(nm)) {
      lines$push(paste0(nm, " = "))
      lines$make_next_sticky()
    }

    lines$push(elts[[i]])

    if (i < n || truncated) {
      lines$push_sticky(", ")
    }
  }

  if (truncated) {
    lines$push("...")
  }

  lines$push_sticky(">")
  lines$decrease_indent()

  lines$get_lines()
}`

const rtdal005903Source0038 = `list_deparse <- function(x, lines = new_lines()) {
  if (!length(x) && !is_null(names(x))) {
    lines$push("<named list>")
    return(lines$get_lines())
  }

  max_elements <- lines$max_elements

  lines$push(paste0("<list: "))
  lines$increase_indent()
  truncated <- !is.null(max_elements) && length(x) > max_elements
  if (truncated) {
    x <- .subset(x, seq_len(max_elements))
  }

  nms <- deparsed_names(x)
  n <- length(x)

  for (i in seq_len(n)) {
    nm <- nms[[i]]
    if (nzchar(nm)) {
      lines$push(paste0(nm, " = "))
      lines$make_next_sticky()
    }

    lines$deparse(x[[i]])

    if (i < n || truncated) {
      lines$push_sticky(", ")
    }
  }

  if (truncated) {
    lines$push("...")
  }

  lines$push_sticky(">")
  lines$decrease_indent()

  lines$get_lines()
}`

const rtdal005903Source0039 = `s3_deparse <- function(x, lines = new_lines()) {
  lines$push(paste0("<", rlang_type_sum(x), ">"))
  lines$get_lines()
}`

const rtdal005903Source0040 = `literal_deparser <- function(type) {
  function(x, lines = new_lines()) {
    lines$push(paste0("<", type, ">"))
  }
}`

const rtdal005903Source0041 = `default_deparse <- function(x, lines = new_lines()) {
  lines$push(deparse(x, control = "keepInteger"))
  lines$get_lines()
}`

const rtdal005903Source0042 = "sexp_deparse <- function(x, lines = new_lines()) {\n  if (is.object(x)) {\n    return(s3_deparse(x, lines))\n  }\n\n  deparser <- switch(\n    typeof(x),\n    symbol = sym_deparse,\n    language = call_deparser(x),\n    closure = fn_deparse,\n    `...` = literal_deparser(\"...\"),\n    any = literal_deparser(\"any\"),\n    environment = literal_deparser(\"environment\"),\n    externalptr = literal_deparser(\"pointer\"),\n    promise = literal_deparser(\"promise\"),\n    weakref = literal_deparser(\"weakref\"),\n    logical = ,\n    integer = ,\n    double = ,\n    complex = ,\n    character = ,\n    raw = atom_deparse,\n    list = list_deparse,\n    default_deparse\n  )\n  deparser(x, lines)\n\n  lines$get_lines()\n}"

const rtdal005903Source0046 = `as_label <- function(x) {
  x <- quo_squash(x)

  if (is_missing(x)) {
    return("<empty>")
  }

  switch(
    typeof(x),
    NULL = "NULL",
    symbol = as_string(x),
    language = {
      if (is_data_pronoun(x)) {
        return(data_pronoun_name(x) %||% "<unknown>")
      }
      if (use_as_label_infix() && infix_overflows(x)) {
        return(as_label_infix(x))
      }

      name <- deparse_one(x)
      name <- gsub("\n.*$", "...", name)
      name
    },
    if (is_bare_atomic(x, n = 1)) {
      name <- expr_text(x)
      name <- gsub("\n.*$", "...", name)
      name
    } else {
      paste0("<", rlang_type_sum(x), ">")
    }
  )
}`

const rtdal005903Source0049 = "as_label_infix <- function(x) {\n  # Shorten the expression if we're too long. Preserve the left side\n  # if possible.\n  infix_n <- nchar_infix(x)\n  dots_n <- 3\n\n  left_width <- 60 - infix_n - dots_n\n  left <- expr_deparse(x[[2]], width = left_width)\n  if (length(left) > 1 || nchar(left) > left_width) {\n    x[[2]] <- quote(...)\n    left_n <- dots_n\n  } else {\n    left_n <- nchar(left)\n  }\n\n  right_width <- 60 - left_n - infix_n\n  right <- expr_deparse(x[[3]], width = right_width)\n  if (length(right) > 1 || nchar(right) > right_width) {\n    x[[3]] <- quote(...)\n  }\n\n  out <- expr_deparse(x, width = 60)\n\n  # In case something went wrong\n  if (length(out) > 1) {\n    if (testing()) {\n      abort(\"Deparsed `out` can't be multiline.\", .internal = TRUE)\n    }\n    paste(out[[1]], \"...\")\n  } else {\n    out\n  }\n}"

