const rtdal005908Source0001 = `env_bind <- function(.env, ...) {
  check_environment(.env)
  invisible(.Call(
    ffi_env_bind,
    env = .env,
    values = list3(...),
    needs_old = TRUE,
    bind_type = "value",
    eval_env = NULL
  ))
}`

const rtdal005908Source0003 = `env_bind_lazy <- function(.env, ..., .eval_env = caller_env()) {
  check_environment(.env)
  invisible(.Call(
    ffi_env_bind,
    env = .env,
    values = exprs(...),
    needs_old = TRUE,
    bind_type = "lazy",
    eval_env = .eval_env
  ))
}`

const rtdal005908Source0004 = `env_bind_active <- function(.env, ...) {
  check_environment(.env)
  invisible(.Call(
    ffi_env_bind,
    env = .env,
    values = list3(...),
    needs_old = TRUE,
    bind_type = "active",
    eval_env = caller_env()
  ))
}`

const rtdal005908Source0005 = "`%<~%` <- function(lhs, rhs) {\n  env <- caller_env()\n  inject(\n    base::delayedAssign(\n      as_string(substitute(lhs)),\n      !!substitute(rhs),\n      eval.env = env,\n      assign.env = env\n    )\n  )\n}"

const rtdal005908Source0006 = `local_bindings <- function(..., .env = .frame, .frame = caller_env()) {
  check_environment(.env)
  check_environment(.frame)

  old <- env_bind(.env, ...)
  defer(env_bind0(.env, old), envir = .frame)

  invisible(old)
}`

const rtdal005908Source0007 = `with_bindings <- function(.expr, ..., .env = caller_env()) {
  check_environment(.env)
  local_bindings(..., .env = .env)
  .expr
}`

const rtdal005908Source0014 = `env_cache <- function(env, nm, default) {
  check_required(default)
  check_string(nm, allow_empty = FALSE)

  if (env_has(env, nm)) {
    env_get(env, nm)
  } else {
    env_poke(env, nm, default)
    default
  }
}`

