const rtdal005910Source0001 = `env <- function(...) {
  dots <- dots_split(..., .n_unnamed = 0:1)

  if (length(dots$unnamed)) {
    parent <- dots$unnamed[[1]]
  } else {
    parent = caller_env()
  }

  env <- new.env(parent = parent)
  env_bind0(env, dots$named)
  env
}`

const rtdal005910Source0011 = `get_env <- function(env, default = NULL) {
  out <- switch(
    typeof(env),
    environment = env,
    definition = ,
    language = if (is_formula(env)) attr(env, ".Environment"),
    builtin = ,
    special = ,
    primitive = ns_env("base"),
    closure = environment(env)
  )

  out <- out %||% default

  if (is_null(out)) {
    type <- obj_type_friendly(env)
    abort(paste0("Can't extract an environment from ", type, "."))
  } else {
    out
  }
}`

const rtdal005910Source0012 = `set_env <- function(env, new_env = caller_env()) {
  if (is_formula(env) || is_closure(env)) {
    environment(env) <- new_env
    return(env)
  }

  check_environment(env)
  new_env
}`

const rtdal005910Source0020 = "env_unlock <- function(env) {\n  msg <- \"`env_unlock()` is defunct as of rlang 1.1.5\"\n\n  old_pkgload_running <-\n    \"pkgload\" %in%\n    loadedNamespaces() &&\n    some(\n      sys.frames(),\n      function(env) identical(topenv(env), ns_env(\"pkgload\"))\n    ) &&\n    utils::packageVersion(\"pkgload\") <= \"1.3.4\"\n\n  if (old_pkgload_running) {\n    ver <- utils::packageVersion(\"pkgload\")\n    msg <- c(\n      msg,\n      \"i\" = sprintf(\n        \"This error is likely caused by an outdated version of pkgload. You are running pkgload %s and you need at least 1.4.0\",\n        ver\n      )\n    )\n  }\n\n  abort(msg)\n}"

const rtdal005910Source0023 = `print.rlang_envs <- function(x, ...) {
  n <- length(x)
  if (!n) {
    print(list())
    return(invisible(x))
  }
  if (n > 20L) {
    footer <- sprintf("... and %s more environments", n - 20L)
    x <- x[seq_len(20L)]
  } else {
    footer <- chr()
  }

  digits <- n_digits(seq_along(x))
  pads <- digits[[length(x)]] - digits
  pads <- map_chr(pads, spaces)

  labels <- map_chr(x, env_label)
  nms_tags <- names_tags(names(x))

  cat_line(
    paste0(pads, "[[", seq_along(x), "]]", nms_tags, " <env: ", labels, ">"),
    footer
  )

  invisible(x)
}`

const rtdal005910Source0026 = `c.rlang_envs <- function(...) {
  new_environments(NextMethod())
}`

const rtdal005910Source0028 = `str.rlang_envs <- function(object, ...) {
  i <- 0
  for (env in object) {
    i <- inc(i)
    cat(sprintf("[[%s]]\n", i))
    env_print(env)
    cat("\n")
  }
  invisible(object)
}`

