const rtdal005913Source0001 = `is_expression <- function(x) {
  stack <- new_stack()
  stack$push(zap_srcref(x))

  while (!is_exhausted(elt <- stack$pop())) {
    if (is_missing(elt)) {
      return(FALSE)
    }

    if (!is_null(attributes(elt))) {
      return(FALSE)
    }

    switch(
      typeof(elt),
      language = stack$push(!!!as.list(elt)),
      if (!is_symbol(elt) && !is_syntactic_literal(elt)) {
        return(FALSE)
      }
    )
  }

  TRUE
}`

const rtdal005913Source0002 = "is_syntactic_literal <- function(x) {\n  # Don't combine the tests, because we want to make sure type is one of these\n  # *before* dispatching on `length()` or `is.na()` or even `attributes()`.\n  switch(\n    typeof(x),\n    NULL = TRUE,\n    logical = ,\n    character = {\n      length(x) == 1 && is.null(attributes(x))\n    },\n    integer = ,\n    double = {\n      length(x) == 1 && is.null(attributes(x)) && (is.na(x) || x >= 0)\n    },\n    complex = {\n      length(x) == 1 && \n        is.null(attributes(x)) && \n        (\n          (is.na(Re(x)) && is.na(Im(x))) || \n            (!is.na(x) && Re(x) == 0 && Im(x) >= 0)\n        )\n    },\n    FALSE\n  )\n}"

const rtdal005913Source0004 = "expr_label <- function(expr) {\n  if (is.character(expr)) {\n    encodeString(expr, quote = '\"')\n  } else if (is.null(expr) || is.atomic(expr)) {\n    format(expr)\n  } else if (is.name(expr)) {\n    paste0(\"`\", as.character(expr), \"`\")\n  } else {\n    chr <- deparse_one(expr)\n    paste0(\"`\", chr, \"`\")\n  }\n}"

const rtdal005913Source0006 = `expr_text <- function(expr, width = 60L, nlines = Inf) {
  if (is_symbol(expr)) {
    return(sym_text(expr))
  }

  str <- deparse(expr, width.cutoff = width, backtick = TRUE)

  if (length(str) > nlines) {
    str <- c(str[seq_len(nlines - 1)], "...")
  }

  paste0(str, collapse = "\n")
}`

const rtdal005913Source0009 = `set_expr <- function(x, value) {
  if (is_quosure(x)) {
    x <- quo_set_expr(x, value)
  } else if (is_formula(x)) {
    f_rhs(x) <- value
  } else if (is_closure(x)) {
    body(x) <- value
  } else {
    x <- value
  }

  x
}`

const rtdal005913Source0011 = `expr_type_of <- function(x) {
  if (is_missing(x)) {
    return("missing")
  }

  type <- typeof(x)
  if (type %in% c("symbol", "language", "pairlist", "NULL")) {
    type
  } else {
    "literal"
  }
}`

const rtdal005913Source0012 = `switch_expr <- function(.x, ...) {
  switch(expr_type_of(.x), ...)
}`

const rtdal005913Source0013 = `expr_print <- function(x, ...) {
  cat_line(expr_deparse(x, ...))
  invisible(x)
}`

const rtdal005913Source0014 = `expr_deparse <- function(x, ..., width = peek_option("width")) {
  check_dots_empty0(...)
  deparser <- new_quo_deparser(width = width)
  quo_deparse(x, deparser)
}`

