const rtdal005915Source0007 = `fn_fmls_syms <- function(fn = caller_fn()) {
  fmls_nms <- fn_fmls_names(fn)
  if (is_null(fmls_nms)) {
    return(list())
  }

  nms <- set_names(fmls_nms)
  names(nms)[match("...", nms)] <- ""
  syms(nms)
}`

const rtdal005915Source0008 = "`fn_fmls<-` <- function(fn, value) {\n  check_closure(fn)\n  attrs <- attributes(fn)\n\n  formals(fn) <- value\n\n  # Work around bug in base R\n  attributes(fn) <- attrs\n\n  fn\n}"

const rtdal005915Source0009 = "`fn_fmls_names<-` <- function(fn, value) {\n  check_closure(fn)\n  attrs <- attributes(fn)\n\n  fmls <- formals(fn)\n  names(fmls) <- value\n  formals(fn) <- fmls\n\n  # Work around bug in base R\n  attributes(fn) <- attrs\n\n  fn\n}"

const rtdal005915Source0010 = `fn_body <- function(fn = caller_fn()) {
  check_closure(fn)

  body <- body(fn)

  if (is_call(body, "{")) {
    body
  } else {
    call("{", body)
  }
}`

const rtdal005915Source0011 = "`fn_body<-` <- function(fn, value) {\n  attrs <- attributes(fn)\n\n  body(fn) <- value\n\n  # Work around bug in base R. First remove source references since\n  # the body has changed\n  attrs$srcref <- NULL\n  attributes(fn) <- attrs\n\n  fn\n}"

const rtdal005915Source0012 = `fn_body_node <- function(fn) {
  body <- body(fn)
  if (is_call(body, "{")) {
    node_cdr(fn)
  } else {
    pairlist(body)
  }
}`

const rtdal005915Source0019 = "`fn_env<-` <- function(x, value) {\n  check_function(x)\n  environment(x) <- value\n  x\n}"

const rtdal005915Source0020 = `as_function <- function(
  x,
  env = global_env(),
  ...,
  arg = caller_arg(x),
  call = caller_env()
) {
  check_dots_empty0(...)

  if (is_function(x)) {
    return(x)
  }

  if (is_quosure(x)) {
    mask <- eval_tidy(call2(environment), env = quo_get_env(x))
    fn <- new_function(pairlist2(... = ), quo_get_expr(x), mask)
    return(fn)
  }

  if (is_formula(x)) {
    if (length(x) > 2) {
      abort_coercion(
        x,
        x_type = "a two-sided formula",
        to_type = "a function",
        arg = arg,
        call = call
      )
    }

    env <- f_env(x)
    if (!is_environment(env)) {
      abort("Formula must carry an environment.", arg = arg, call = call)
    }

    args <- list(
      ... = missing_arg(),
      .x = quote(..1),
      .y = quote(..2),
      . = quote(..1)
    )
    fn <- new_function(args, f_rhs(x), env)
    fn <- structure(fn, class = c("rlang_lambda_function", "function"))
    return(fn)
  }

  if (is_string(x)) {
    return(get(x, envir = env, mode = "function"))
  }

  abort_coercion(x, "a function", arg = arg, call = call)
}`

const rtdal005915Source0021 = `print.rlang_lambda_function <- function(x, ...) {
  cat_line("<lambda>")
  NextMethod()
}`

const rtdal005915Source0024 = "prim_args <- function(fmls) {\n  args <- names(fmls)\n\n  # Set argument names but only after `...`. Arguments before dots\n  # should be positionally matched.\n  dots_i <- match(\"...\", args)\n  if (!is_na(dots_i)) {\n    idx <- seq2(dots_i + 1L, length(args))\n    names2(args)[idx] <- args[idx]\n  }\n\n  syms(args)\n}"

