const rtdal005915Source0026 = "op_as_closure <- function(prim_nm) {\n  switch(\n    prim_nm,\n    `<-` = ,\n    `<<-` = ,\n    `=` = function(.x, .y) {\n      op <- sym(prim_nm)\n      expr <- expr((!!op)(!!enexpr(.x), !!enexpr(.y)))\n      eval_bare(expr, caller_env())\n    },\n    `@` = ,\n    `$` = function(.x, .i) {\n      op <- sym(prim_nm)\n      expr <- expr((!!op)(.x, !!quo_squash(enexpr(.i), warn = TRUE)))\n      eval_bare(expr)\n    },\n    `[[<-` = function(.x, .i, .value) {\n      expr <- expr((!!enexpr(.x))[[!!enexpr(.i)]] <- !!enexpr(.value))\n      eval_bare(expr, caller_env())\n    },\n    `[<-` = function(.x, ...) {\n      args <- exprs(...)\n      n <- length(args)\n      if (n < 2L) {\n        abort(\"Must supply operands to `[<-`.\")\n      }\n      expr <- expr((!!enexpr(.x))[!!!args[-n]] <- !!args[[n]])\n      eval_bare(expr, caller_env())\n    },\n    `@<-` = function(.x, .i, .value) {\n      expr <- expr(`@`(!!enexpr(.x), !!enexpr(.i)) <- !!enexpr(.value))\n      eval_bare(expr, caller_env())\n    },\n    `$<-` = function(.x, .i, .value) {\n      expr <- expr(`$`(!!enexpr(.x), !!enexpr(.i)) <- !!enexpr(.value))\n      eval_bare(expr, caller_env())\n    },\n    `(` = function(.x) .x,\n    `[` = function(.x, ...) .x[...],\n    `[[` = function(.x, ...) .x[[...]],\n    `{` = function(...) {\n      values <- list(...)\n      values[[length(values)]]\n    },\n    `&` = new_binary_closure(function(.x, .y) .x & .y),\n    `|` = new_binary_closure(function(.x, .y) .x | .y),\n    `&&` = new_binary_closure(function(.x, .y) .x && .y),\n    `||` = new_binary_closure(\n      function(.x, .y) .x || .y,\n      shortcircuiting = TRUE\n    ),\n    `!` = function(.x) !.x,\n    `+` = new_binary_closure(\n      function(.x, .y) if (missing(.y)) .x else .x + .y,\n      versatile = TRUE\n    ),\n    `-` = new_binary_closure(\n      function(.x, .y) if (missing(.y)) -.x else .x - .y,\n      versatile = TRUE\n    ),\n    `*` = new_binary_closure(function(.x, .y) .x * .y),\n    `/` = new_binary_closure(function(.x, .y) .x / .y),\n    `^` = new_binary_closure(function(.x, .y) .x^.y),\n    `%%` = new_binary_closure(function(.x, .y) .x %% .y),\n    `<` = new_binary_closure(function(.x, .y) .x < .y),\n    `<=` = new_binary_closure(function(.x, .y) .x <= .y),\n    `>` = new_binary_closure(function(.x, .y) .x > .y),\n    `>=` = new_binary_closure(function(.x, .y) .x >= .y),\n    `==` = new_binary_closure(function(.x, .y) .x == .y),\n    `!=` = new_binary_closure(function(.x, .y) .x != .y),\n    `:` = new_binary_closure(function(.x, .y) .x:.y),\n    `~` = function(.x, .y) {\n      if (is_missing(substitute(.y))) {\n        new_formula(NULL, substitute(.x), caller_env())\n      } else {\n        new_formula(substitute(.x), substitute(.y), caller_env())\n      }\n    },\n\n    `c` = function(...) c(...),\n    seq.int = function(from = 1L, to = from, ...) seq.int(from, to, ...),\n\n    # Unsupported primitives\n    `break` = ,\n    `for` = ,\n    `function` = ,\n    `if` = ,\n    `next` = ,\n    `repeat` = ,\n    `return` = ,\n    `while` = {\n      nm <- chr_quoted(prim_nm)\n      abort(paste0(\n        \"Can't coerce the primitive function \",\n        nm,\n        \" to a closure.\"\n      ))\n    }\n  )\n}"

const rtdal005915Source0027 = `new_binary_closure <- function(fn, versatile = FALSE, shortcircuiting = FALSE) {
  if (versatile) {
    nodes <- versatile_check_nodes
  } else if (shortcircuiting) {
    nodes <- shortcircuiting_check_nodes
  } else {
    nodes <- binary_check_nodes
  }

  nodes <- duplicate(nodes, shallow = TRUE)
  nodes <- node_append(nodes, fn_body_node(fn))
  body <- new_call(brace_sym, nodes)

  formals(fn) <- binary_fmls
  body(fn) <- body

  fn
}`

const rtdal005915Source0029 = "binary_check_nodes <- pairlist(\n  quote(\n    if (missing(.x)) {\n      if (missing(e1)) {\n        abort(\"Must supply `e1` or `.x` to binary operator.\")\n      }\n      .x <- e1\n    } else if (!missing(e1)) {\n      abort(\"Can't supply both `e1` and `.x` to binary operator.\")\n    }\n  ),\n  quote(\n    if (missing(.y)) {\n      if (missing(e2)) {\n        abort(\"Must supply `e2` or `.y` to binary operator.\")\n      }\n      .y <- e2\n    } else if (!missing(e2)) {\n      abort(\"Can't supply both `e2` and `.y` to binary operator.\")\n    }\n  )\n)"

const rtdal005915Source0030 = "versatile_check_nodes <- as.pairlist(c(\n  binary_check_nodes[[1]],\n  quote(\n    if (missing(.y) && !missing(e2)) {\n      .y <- e2\n    } else if (!missing(e2)) {\n      abort(\"Can't supply both `e2` and `.y` to binary operator.\")\n    }\n  )\n))"

const rtdal005915Source0031 = `shortcircuiting_check_nodes <- as.pairlist(c(
  binary_check_nodes[[1]],
  quote(if (.x) return(TRUE)),
  binary_check_nodes[[2]]
))`

const rtdal005915Source0032 = "as_predicate <- function(.fn, ...) {\n  .fn <- as_function(.fn)\n\n  function(...) {\n    out <- .fn(...)\n\n    if (!is_bool(out)) {\n      abort(sprintf(\n        \"Predicate functions must return a single `TRUE` or `FALSE`, not %s\",\n        as_predicate_friendly_type_of(out)\n      ))\n    }\n\n    out\n  }\n}"

const rtdal005915Source0033 = `as_predicate_friendly_type_of <- function(x) {
  if (is_na(x)) {
    "a missing value"
  } else {
    obj_type_friendly(x)
  }
}`

