const rtdal005919Source0045 = `as_integerish_type <- function(x, as_type, to, value = FALSE) {
  if (is_integerish(x)) {
    as_base_type(x, as_type)
  } else {
    abort(paste0(
      "Can't convert a fractional double vector to ",
      obj_type_friendly(to, value = value),
      ""
    ))
  }
}`

const rtdal005919Source0046 = `coerce_type_vec <- function(.x, .to, ...) {
  # Cannot reuse coerce_type() because switch() has a bug with
  # fallthrough and multiple levels of dots forwarding.
  out <- switch(type_of_(.x), ..., abort_coercion(.x, .to, call = NULL))

  if (!is_null(names(.x))) {
    names(out) <- names(.x)
  }

  out
}`

const rtdal005919Source0049 = "ctxt_frame <- function(n = 1) {\n  deprecate_warn(\"`ctxt_frame()` is deprecated as of rlang 0.3.0.\")\n  stopifnot(n > 0)\n  pos <- sys.nframe() - n\n\n  if (pos < 0L) {\n    stop(\"not that many frames on the stack\", call. = FALSE)\n  } else if (pos == 0L) {\n    global_frame()\n  } else {\n    new_frame(list(\n      pos = pos,\n      caller_pos = sys.parent(n + 1),\n      expr = sys.call(-n),\n      env = sys.frame(-n),\n      fn = sys.function(-n),\n      fn_name = call_name(sys.call(-n))\n    ))\n  }\n}"

const rtdal005919Source0053 = `expr_interp <- function(x, env = NULL) {
  if (is_formula(x)) {
    f_rhs(x) <- .Call(ffi_interp, f_rhs(x), env %||% f_env(x))
  } else if (is_closure(x)) {
    body(x) <- .Call(ffi_interp, body(x), env %||% fn_env(x))
  } else {
    x <- .Call(ffi_interp, x, env %||% parent.frame())
  }
  x
}`

