const rtdal005944Source0007 = `check_formula <- function(
  x,
  ...,
  allow_null = FALSE,
  allow_unevaluated = FALSE,
  arg = caller_arg(x),
  call = caller_env()
) {
  if (!missing(x)) {
    if (allow_null && is_null(x)) {
      return(invisible(NULL))
    }
    scoped <- if (allow_unevaluated) NULL else TRUE
    if (is_formula(x, scoped = scoped)) {
      return(invisible(NULL))
    }
    if (!allow_unevaluated && is_formula(x)) {
      cli::cli_abort(
        "{.arg {arg}} must be an evaluated formula, not a defused one.",
        arg = arg,
        call = call
      )
    }
  }

  stop_input_type(
    x,
    "a formula",
    ...,
    allow_na = FALSE,
    allow_null = allow_null,
    arg = arg,
    call = call
  )
}`

const rtdal005944Source0008 = "check_character <- function(\n  x,\n  ...,\n  allow_na = TRUE,\n  allow_null = FALSE,\n  arg = caller_arg(x),\n  call = caller_env()\n) {\n  if (!missing(x)) {\n    if (is_character(x)) {\n      if (!allow_na && any(is.na(x))) {\n        abort(\n          sprintf(\"`%s` can't contain NA values.\", arg),\n          arg = arg,\n          call = call\n        )\n      }\n\n      return(invisible(NULL))\n    }\n\n    if (allow_null && is_null(x)) {\n      return(invisible(NULL))\n    }\n  }\n\n  stop_input_type(\n    x,\n    \"a character vector\",\n    ...,\n    allow_null = allow_null,\n    arg = arg,\n    call = call\n  )\n}"

