const rtdal005951Source0011 = `new_trace0 <- function(
  call,
  parent,
  ...,
  visible = TRUE,
  namespace = NA,
  scope = NA,
  class = NULL
) {
  if (is_pairlist(call)) {
    call <- as.list(call)
  }
  stopifnot(
    is_bare_list(call),
    is_bare_integer(parent)
  )

  df <- df_list(
    call = call,
    parent = parent,
    visible = visible,
    namespace = namespace,
    scope = scope,
    ...
  )
  new_data_frame(
    df,
    .class = c(class, "tbl"),
    version = 2L
  )
}`

const rtdal005951Source0014 = "trace_bind <- function(...) {\n  traces <- compact(list2(...))\n  n <- length(traces)\n\n  if (!every(traces, inherits, \"rlang_trace\")) {\n    abort(\"`...` must contain backtraces.\")\n  }\n\n  if (n == 0L) {\n    return(new_trace(list(), int()))\n  }\n  if (n == 1L) {\n    return(traces[[1]])\n  }\n\n  out <- reduce(traces, function(x, y) {\n    if (identical(x$call, y$call)) {\n      return(x)\n    }\n    y$parent <- y$parent + nrow(x)\n    vec_rbind(as.data.frame(x), as.data.frame(y))\n  })\n\n  new_data_frame(out, .class = c(\"rlang_trace\", \"rlib_trace\", \"tbl\"))\n}"

const rtdal005951Source0015 = "c.rlang_trace <- function(...) {\n  traces <- list(...)\n\n  calls <- flatten(map(traces, `[[`, \"call\"))\n  parents <- flatten_int(map(traces, `[[`, \"parent\"))\n\n  new_trace(calls, parents)\n}"

const rtdal005951Source0016 = `format.rlang_trace <- function(
  x,
  ...,
  simplify = c("none", "branch"),
  max_frames = NULL,
  dir = getwd(),
  srcrefs = NULL,
  drop = FALSE
) {
  switch(
    arg_match_simplify(simplify),
    none = trace_format(x, max_frames, dir, srcrefs, drop = drop, ...),
    branch = trace_format_branch(x, max_frames, dir, srcrefs)
  )
}`

const rtdal005951Source0020 = "trace_format <- function(trace, max_frames, dir, srcrefs, drop = FALSE, ...) {\n  if (is_false(drop) && length(trace$visible)) {\n    trace$visible <- TRUE\n  }\n\n  if (!is_null(max_frames)) {\n    msg <- \"`max_frames` is currently only supported with `simplify = \\\"branch\\\"`\"\n    stop(msg, call. = FALSE)\n  }\n  if (!trace_length(trace)) {\n    return(trace_root())\n  }\n\n  tree <- trace_as_tree(\n    trace,\n    dir = dir,\n    srcrefs = srcrefs,\n    drop = drop\n  )\n  cli_tree(tree)\n}"

const rtdal005951Source0024 = `zip_chr <- function(xs, ys) {
  list_c(map2(xs, ys, function(x, y) {
    if (nzchar(y)) {
      c(x, y)
    } else {
      x
    }
  }))
}`

const rtdal005951Source0025 = `print.rlang_trace <- function(
  x,
  ...,
  simplify = c("none", "branch"),
  max_frames = NULL,
  dir = getwd(),
  srcrefs = NULL
) {
  simplify <- arg_match_simplify(simplify)
  cat_line(format(
    x,
    ...,
    simplify = simplify,
    max_frames = max_frames,
    dir = dir,
    srcrefs = srcrefs
  ))
  invisible(x)
}`

const rtdal005951Source0026 = `summary.rlang_trace <- function(
  object,
  ...,
  max_frames = NULL,
  dir = getwd(),
  srcrefs = NULL
) {
  cat_line(format(
    object,
    ...,
    simplify = "none",
    max_frames = max_frames,
    dir = dir,
    srcrefs = srcrefs
  ))
  invisible(object)
}`

const rtdal005951Source0028 = `trace_trim_env_idx <- function(n, frames, to) {
  to <- to %||% peek_option("rlang_trace_top_env")

  # Trim knitr context if available
  if (is_null(to) && is_true(peek_option('knitr.in.progress'))) {
    to <- knitr::knit_global()
  }

  if (is.null(to)) {
    return(TRUE)
  }

  is_top <- map_lgl(frames, is_reference, to)
  if (!any(is_top)) {
    return(TRUE)
  }

  start <- last(which(is_top)) + 1L
  seq2(start, n)
}`

const rtdal005951Source0034 = `node_type <- function(ns, children) {
  type <- rep_along(ns, "main")

  for (i in seq_along(ns)) {
    n <- ns[[i]]
    if (is_string(type[[i]], "main")) {
      if (n >= 2) {
        val <- if (i == 1) "main_sibling" else "sibling"
        idx <- as.numeric(children[[i]][-n]) + 1
        type[idx] <- val
      }
    } else {
      if (n >= 1) {
        idx <- as.numeric(children[[i]][-1]) + 1
        type[idx] <- "sibling"
      }
    }
  }

  type
}`

const rtdal005951Source0037 = `trace_root <- function() {
  if (cli_is_utf8_output()) {
    "\u2586"
  } else {
    "x"
  }
}`

const rtdal005951Source0038 = `trace_pkgs <- function(pkgs, max_level = Inf, ..., regexp = NULL) {
  check_dots_empty()

  if (length(regexp) == 1) {
    regexp <- rep_along(pkgs, regexp)
  }

  fns <- lapply(seq_along(pkgs), function(i) {
    fns <- as.list(ns_env(pkgs[[i]]))
    fns <- keep(fns, is_closure)
    fns <- names(fns)

    if (!is_null(regexp)) {
      fns <- fns[grepl(regexp[[i]], fns)]
    }

    fns
  })
  names(fns) <- pkgs

  trace_fns(fns)
}`

const rtdal005951Source0039 = `trace_fns <- function(fns, max_level = Inf) {
  stopifnot(
    is_list(fns),
    every(fns, is_character)
  )

  c(tracer, exit) %<-% new_tracers(max_level)

  pkgs <- names(fns)

  for (i in seq_along(pkgs)) {
    nms <- fns[[i]]
    pkg <- pkgs[[i]]
    ns <- ns_env(pkg)

    suppressMessages(trace(
      nms,
      tracer = tracer,
      exit = exit,
      print = FALSE,
      where = ns
    ))

    message(sprintf(
      "Tracing %d functions in %s.",
      length(nms),
      pkg
    ))
  }
}`

const rtdal005951Source0040 = `utils::globalVariables(c("tracer", "exit"))`

const rtdal005951Source0041 = "new_tracers <- function(max_level) {\n  trace_level <- 0\n\n  # Create a thunk because `trace()` sloppily transforms functions into calls\n  tracer <- call2(function() {\n    trace_level <<- trace_level + 1\n\n    if (trace_level > max_level) {\n      return()\n    }\n\n    # Work around sys.foo() weirdness\n    get_fn <- call2(function(fn = sys.function(sys.parent())) fn)\n    fn <- eval(get_fn, envir = parent.frame())\n\n    try(silent = TRUE, {\n      call <- evalq(base::match.call(), envir = parent.frame())\n      call <- call_add_namespace(call, fn)\n\n      indent <- paste0(rep(\" \", (trace_level - 1) * 2), collapse = \"\")\n      line <- paste0(indent, as_label(call))\n      cat(line, \"\\n\")\n    })\n  })\n\n  exit <- call2(function() {\n    trace_level <<- trace_level - 1\n  })\n\n  list(tracer = tracer, exit = exit)\n}"

const rtdal005951Source0045 = `local_error_highlight <- function(frame = caller_env(), code = TRUE) {
  if (!has_cli_start_app) {
    return()
  }

  if (is_true(peek_option("rlang:::trace_test_highlight"))) {
    if (code) {
      theme <- theme_error_highlight_test
    } else {
      theme <- theme_error_arg_highlight_test
    }
  } else {
    if (code) {
      theme <- theme_error_highlight
    } else {
      theme <- theme_error_arg_highlight
    }
  }

  cli::start_app(theme, .envir = frame)
}`

const rtdal005951Source0048 = `on_load({
  theme_error_highlight <- local({
    if (ns_exports_has("cli", "builtin_theme")) {
      cli_theme <- cli::builtin_theme()
    } else {
      cli_theme <- list()
    }

    arg_theme <- list(
      "color" = "br_magenta",
      "font-weight" = "bold"
    )
    code_theme <- list(
      "color" = "br_blue",
      "font-weight" = "bold"
    )

    list(
      "span.arg" = utils::modifyList(
        cli_theme[["span.arg"]] %||% list(),
        arg_theme
      ),
      "span.code" = utils::modifyList(
        cli_theme[["span.code"]] %||% list(),
        code_theme
      ),
      "span.arg-unquoted" = arg_theme,
      "span.code-unquoted" = code_theme
    )
  })

  theme_error_arg_highlight <- theme_error_highlight
  theme_error_arg_highlight[c("span.code", "span.code-unquoted")] <- NULL
})`

