const rtdal005956Source0063 = `rlang_type_sum.default <- function(x) {
  if (!is.object(x)) {
    switch(
      typeof(x),
      logical = "lgl",
      integer = "int",
      double = "dbl",
      character = "chr",
      complex = "cpl",
      builtin = ,
      special = ,
      closure = "fn",
      environment = "env",
      symbol = if (is_missing(x)) {
        "missing"
      } else {
        "sym"
      },
      typeof(x)
    )
  } else if (!isS4(x)) {
    paste0("S3: ", class(x)[[1]])
  } else {
    paste0("S4: ", methods::is(x)[[1]])
  }
}`

