const rtdal005959Source0032 = `style_dim_soft <- function(x) {
  if (!has_ansi()) {
    return(x)
  }
  if (cli::num_ansi_colors() >= 256) {
    crayon::make_style(grDevices::grey(0.6), colors = 256)(x)
  } else {
    col_silver(x)
  }
}`

const rtdal005959Source0033 = `strip_trailing_newline <- function(x) {
  n <- nchar(x)
  if (substr(x, n, n) == "\n") {
    substr(x, 0, n - 1L)
  } else {
    x
  }
}`

