const rtdal005959Source0036 = `stop_internal <- function(message, ..., call = caller_env(2)) {
  abort(message, ..., call = call, .internal = TRUE)
}`

const rtdal005959Source0040 = `new_stack <- function() {
  stack <- new_dyn_vector("list", 100)

  push <- function(...) {
    for (obj in list2(...)) {
      dyn_push_back(stack, maybe_missing(obj))
    }
  }

  # Can be used as a coro generator
  pop <- function() {
    if (dyn_count(stack)) {
      dyn_pop_back(stack)
    } else {
      exhausted()
    }
  }

  new_environment(list(
    push = push,
    pop = pop
  ))
}`

const rtdal005959Source0043 = `path_trim_prefix <- function(path, n) {
  split <- strsplit(path, "/")[[1]]
  n_split <- length(split)

  if (n_split <= n) {
    path
  } else {
    paste(split[seq2(n_split - n + 1, n_split)], collapse = "/")
  }
}`

const rtdal005959Source0044 = "browser <- function(..., skipCalls = 0, frame = parent.frame()) {\n  if (!identical(stdout(), getConnection(1))) {\n    sink(getConnection(1))\n    withr::defer(sink(), envir = frame)\n  }\n\n  # Calling `browser()` on exit avoids RStudio displaying the\n  # `browser2()` location. We still need one `n` to get to the\n  # expected place. Ideally `skipCalls` would not skip but exit the\n  # contexts.\n  on.exit(base::browser(..., skipCalls = skipCalls + 1))\n}"

