const rtdal005991Source0001 = `test_that("names2() takes care of missing values", {
  x <- set_names(1:3, c("a", NA, "b"))
  expect_identical(names2(x), c("a", "", "b"))
})`

const rtdal005991Source0002 = "test_that(\"names2() fails for environments\", {\n  expect_error(\n    names2(env()),\n    \"Use `env_names()` for environments.\",\n    fixed = TRUE\n  )\n})"

const rtdal005991Source0003 = `test_that("names2<- doesn't add missing values (#1301)", {
  x <- 1:3
  names2(x)[1:2] <- "foo"
  expect_equal(names(x), c("foo", "foo", ""))
})`

const rtdal005991Source0004 = `test_that("inputs must be valid", {
  expect_snapshot(error = TRUE, cnd_class = TRUE, {
    set_names(environment())
    set_names(1:10, letters[1:4])
  })
})`

const rtdal005991Source0005 = `test_that("can supply vector or ...", {
  expect_named(set_names(1:2, c("a", "b")), c("a", "b"))
  expect_named(set_names(1:2, "a", "b"), c("a", "b"))
  expect_named(set_names(1:2, 1, 2), c("1", "2"))
})`

const rtdal005991Source0006 = `test_that("can supply function/formula to rename", {
  x <- c(a = 1, b = 2)
  expect_named(set_names(x, toupper), c("A", "B"))
  expect_named(set_names(x, ~ toupper(.)), c("A", "B"))
  expect_named(set_names(x, paste, "foo"), c("a foo", "b foo"))
})`

const rtdal005991Source0007 = `test_that("set_names() zaps names", {
  expect_null(names(set_names(mtcars, NULL)))
})`

const rtdal005991Source0008 = "test_that(\"set_names() coerces to character\", {\n  expect_identical(set_names(1L, TRUE), c(`TRUE` = 1L))\n  expect_identical(set_names(1:2, \"a\", TRUE), c(a = 1L, `TRUE` = 2L))\n})"

const rtdal005991Source0009 = `test_that("set_names() checks length generically", {
  x <- as.POSIXlt("1970-01-01", tz = "UTC")

  expect <- x
  names(expect) <- "a"

  expect_identical(set_names(x, "a"), expect)
  expect_error(set_names(x, c("a", "b")), "must be compatible")
})`

const rtdal005991Source0010 = "test_that(\"has_name() works with pairlists\", {\n  expect_true(has_name(fn_fmls(`[.data.frame`), \"drop\"))\n})"

const rtdal005991Source0011 = `test_that("set_names() first names the vector before applying a function (#688)", {
  exp <- set_names(letters, toupper(letters))
  expect_identical(set_names(set_names(letters), toupper), exp)
  expect_identical(set_names(letters, toupper), exp)
})`

const rtdal005991Source0012 = `test_that("set_names2() fills in empty names", {
  chr <- c("a", b = "B", "c")
  expect_equal(set_names2(chr), c(a = "a", b = "B", c = "c"))
})`

const rtdal005991Source0013 = `test_that("zap_srcref() removes source references", {
  with_srcref("x <- quote({ NULL })")
  expect_null(attributes(zap_srcref(x)))
})`

const rtdal005991Source0014 = "test_that(\"zap_srcref() handles nested functions (r-lib/testthat#1228)\", {\n  with_srcref(\n    \"\n    factory <- function() {\n      function() {\n        function() {\n          1\n        }\n      }\n    }\"\n  )\n\n  fn <- zap_srcref(factory())\n  expect_null(attributes(fn))\n\n  curly <- body(fn)\n  expect_null(attributes(curly))\n\n  fn_call <- curly[[2]]\n  expect_null(attributes(fn_call))\n\n  # Calls to `function` store srcrefs in 4th cell\n  expect_length(fn_call, 3)\n\n  # Can call `zap_srcref()` repeatedly\n  expect_equal(\n    zap_srcref(fn),\n    fn\n  )\n\n  # Check that `factory` hasn't been modified by reference\n  expect_true(\"srcref\" %in% names(attributes(factory)))\n\n  curly <- body(factory)\n  expect_true(\"srcref\" %in% names(attributes(curly)))\n\n  fn_call <- curly[[2]]\n  expect_length(fn_call, 4)\n})"

const rtdal005991Source0015 = `test_that("zap_srcref() works with quosures", {
  with_srcref("x <- expr({ !!quo({ NULL }) })")

  out <- zap_srcref(x)
  expect_null(attributes(out))

  quo <- out[[2]]
  expect_null(attributes(quo_get_expr(quo)))
})`

const rtdal005991Source0016 = "test_that(\"zap_srcref() preserves attributes\", {\n  with_srcref(\n    \"fn <- structure(function() NULL, bar = TRUE)\"\n  )\n\n  out <- zap_srcref(fn)\n  expect_equal(attributes(out), list(bar = TRUE))\n  expect_null(attributes(body(out)))\n\n  # `fn` attributes are not mutated\n  expect_equal(attr(fn, \"bar\"), TRUE)\n  expect_s3_class(attr(fn, \"srcref\"), \"srcref\")\n})"

