const rtdal005991Source0019 = "test_that(\"is_named2() always returns `TRUE` for empty vectors (#191)\", {\n  expect_false(is_named(chr()))\n  expect_false(is_named(\"a\"))\n\n  expect_true(is_named2(chr()))\n  expect_false(is_named2(\"a\"))\n})"

const rtdal005991Source0020 = `test_that("zap_srcref() supports expression vectors", {
  xs <- parse(text = "{ foo }; bar", keep.source = TRUE)
  zapped <- zap_srcref(xs)

  expect_null(attributes(zapped))
  expect_null(attributes(zapped[[1]]))

  expect_true("srcref" %in% names(attributes(xs)))
  expect_true("srcref" %in% names(attributes(xs[[1]])))
})`

const rtdal005991Source0021 = `test_that("zap_srcref() works on calls", {
  # E.g. srcrefs attached to the call stack

  with_srcref(
    "{
    f <- function() g()
    g <- function() sys.call()
  }"
  )
  call <- f()

  expect_null(attributes(zap_srcref(call)))
  expect_contains(names(attributes(call)), "srcref")
})`

const rtdal005991Source0022 = `test_that("is_dictionaryish return true if is NULL", {
  expect_true(is_dictionaryish(NULL))
})`

