const rtdal005995Source0045 = "test_that(\"`parent = NA` signals a non-chained rethrow\", {\n  variant <- if (getRversion() < \"3.6.0\") \"pre-3.6.0\" else \"current\"\n\n  local_options(\n    rlang_trace_top_env = current_env(),\n    rlang_trace_format_srcrefs = FALSE\n  )\n\n  ff <- function() gg()\n  gg <- function() hh()\n\n  foo <- function() bar()\n  bar <- function() baz()\n  baz <- function() stop(\"bar\")\n\n  expect_snapshot(variant = variant, {\n    \"Absent parent causes bad trace bottom\"\n    hh <- function() {\n      withCallingHandlers(foo(), error = function(cnd) {\n        abort(cnd_header(cnd))\n      })\n    }\n    print(err(ff()))\n\n    \"Missing parent allows correct trace bottom\"\n    hh <- function() {\n      withCallingHandlers(foo(), error = function(cnd) {\n        abort(cnd_header(cnd), parent = NA)\n      })\n    }\n    print(err(ff()))\n\n    \"Wrapped handler\"\n    handler1 <- function(cnd, call = caller_env()) {\n      handler2(cnd, call)\n    }\n    handler2 <- function(cnd, call) {\n      abort(cnd_header(cnd), parent = NA, call = call)\n    }\n    hh <- function() {\n      withCallingHandlers(\n        foo(),\n        error = function(cnd) handler1(cnd)\n      )\n    }\n    print(err(ff()))\n\n    \"Wrapped handler, `try_fetch()`\"\n    hh <- function() {\n      try_fetch(\n        foo(),\n        error = function(cnd) handler1(cnd)\n      )\n    }\n    print(err(ff()))\n\n    \"Wrapped handler, incorrect `call`\"\n    hh <- function() {\n      withCallingHandlers(\n        foo(),\n        error = handler1\n      )\n    }\n    print(err(ff()))\n  })\n})"

