const rtdal005995Source0047 = "test_that(\"if `call` is older than handler caller, use that as bottom\", {\n  local_options(\n    rlang_trace_format_srcrefs = FALSE\n  )\n  f <- function() helper()\n  helper <- function(call = caller_env()) {\n    try_fetch(\n      low_level(call),\n      error = function(cnd) {\n        abort(\n          \"Problem.\",\n          parent = cnd,\n          call = call\n        )\n      }\n    )\n  }\n\n  expect_snapshot({\n    low_level <- function(call) {\n      abort(\"Tilt.\", call = call)\n    }\n    print(expect_error(f()))\n\n    low_level <- function(call) {\n      abort(\"Tilt.\", call = list(NULL, frame = call))\n    }\n    print(expect_error(f()))\n  })\n})"

