const rtdal005998Source0001 = `test_that("format_error_bullets() formats bullets depending on names", {
  expect_equal(format_error_bullets(c("foo", "bar")), "* foo\n* bar")
  expect_equal(
    format_error_bullets(c(i = "foo", "*" = "baz", x = "bar", v = "bam")),
    "i foo\n* baz\nx bar\nv bam"
  )
  expect_equal(format_error_bullets(c(i = "foo", u = "bar")), "i foo\nbar")
  expect_equal(format_error_bullets(chr()), chr())
})`

const rtdal005998Source0002 = "test_that(\"default conditionMessage() method for rlang errors calls cnd_message()\", {\n  # Fallback\n  out <- conditionMessage(error_cnd(\"rlang_foobar\", message = \"embedded\"))\n  expect_identical(out, \"embedded\")\n\n  # Only `cnd_header()` method\n  out <- with_methods(\n    cnd_header.rlang_foobar = function(cnd, ...) \"dispatched!\",\n    conditionMessage(error_cnd(\"rlang_foobar\", message = \"embedded\"))\n  )\n  expect_identical(out, \"dispatched!\")\n\n  # Both `cnd_header()` and `cnd_body()` methods\n  out <- with_methods(\n    cnd_header.rlang_foobar = function(cnd, ...) \"dispatched!\",\n    cnd_body.rlang_foobar = function(cnd, ...) c(\"one\", \"two\", \"three\"),\n    conditionMessage(error_cnd(\"rlang_foobar\", message = \"embedded\"))\n  )\n  exp <- paste0(\"dispatched!\\n\", paste_line(c(\"one\", \"two\", \"three\")))\n  expect_identical(out, exp)\n\n  # All three methods defined\n  out <- with_methods(\n    cnd_header.rlang_foobar = function(cnd, ...) \"dispatched!\",\n    cnd_body.rlang_foobar = function(cnd, ...) c(\"one\", \"two\", \"three\"),\n    cnd_footer.rlang_foobar = function(cnd, ...) c(\"foo\", \"bar\"),\n    conditionMessage(error_cnd(\"rlang_foobar\", message = \"embedded\"))\n  )\n  exp <- paste0(exp, \"\\nfoo\\nbar\")\n  expect_identical(out, exp)\n})"

const rtdal005998Source0003 = `test_that("can override header, body, and footer methods with fields", {
  local_methods(cnd_body.rlang_foobar = function(...) "wrong")

  expect_error(
    stop(error_cnd(
      "rlang_foobar",
      message = "header",
      body = "body"
    )),
    "header\nbody",
    class = "rlang_foobar"
  )
  expect_error(
    stop(error_cnd(
      "rlang_foobar",
      header = "header",
      body = "body",
      footer = "footer"
    )),
    "header\nbody\nfooter",
    class = "rlang_foobar"
  )

  # Also messages and warnings
  expect_message(
    message(message_cnd(
      "rlang_foobar",
      header = ~"header",
      body = ~"body",
      footer = ~"footer"
    )),
    "header\nbody\nfooter",
    class = "rlang_foobar"
  )
  expect_warning(
    warning(warning_cnd(
      "rlang_foobar",
      header = function(...) "header",
      body = function(...) "body",
      footer = function(...) "footer"
    )),
    "header\nbody\nfooter",
    class = "rlang_foobar"
  )

  expect_error(
    stop(error_cnd(
      "rlang_foobar",
      message = "header",
      body = ~ format_error_bullets("body")
    )),
    "header\n* body",
    fixed = TRUE,
    class = "rlang_foobar"
  )
})`

