const rtdal005998Source0026 = "test_that(\"ANSI escapes are supported in `conditionMessage()`\", {\n  skip_if_not_installed(\"cli\")\n\n  foo <- error_cnd(\n    \"foo\",\n    message = \"Parent message.\",\n    use_cli_format = TRUE\n  )\n  bar <- error_cnd(\n    \"bar\",\n    message = \"Message.\",\n    parent = foo,\n    use_cli_format = TRUE\n  )\n\n  testthat::local_reproducible_output(\n    unicode = FALSE,\n    crayon = FALSE\n  )\n  out_bare <- conditionMessage(bar)\n\n  testthat::local_reproducible_output(\n    unicode = TRUE,\n    crayon = TRUE\n  )\n  out_ansi <- conditionMessage(bar)\n\n  expect_equal(out_bare, cli::ansi_strip(out_ansi))\n})"

const rtdal005998Source0027 = `test_that("as.character() and conditionMessage() methods for errors, warnings, and messages", {
  parent_cnd <- error_cnd(
    "foo",
    message = "Parent message.",
    body = c("*" = "Bullet 1.", "*" = "Bullet 2."),
    call = call("foo"),
    use_cli_format = TRUE
  )

  cnd_with <- function(ctor, parent = FALSE) {
    ctor(
      "bar",
      message = "Message.",
      body = c("*" = "Bullet A.", "*" = "Bullet B."),
      call = call("bar"),
      parent = if (parent) parent_cnd,
      use_cli_format = TRUE
    )
  }

  expect_snapshot(cran = TRUE, {
    cat(as.character(cnd_with(error_cnd)))
    cat(as.character(cnd_with(warning_cnd)))
    cat(as.character(cnd_with(message_cnd)))

    cat(as.character(cnd_with(error_cnd, parent = TRUE)))
    cat(as.character(cnd_with(warning_cnd, parent = TRUE)))
    cat(as.character(cnd_with(message_cnd, parent = TRUE)))

    cat(conditionMessage(cnd_with(error_cnd)))
    cat(conditionMessage(cnd_with(warning_cnd)))
    cat(conditionMessage(cnd_with(message_cnd)))

    cat(conditionMessage(cnd_with(error_cnd, parent = TRUE)))
    cat(conditionMessage(cnd_with(warning_cnd, parent = TRUE)))
    cat(conditionMessage(cnd_with(message_cnd, parent = TRUE)))
  })
})`

