const rtdal005999Source0020 = "test_that(\"`inform()` behaves consistently in interactive and non-interactive sessions (#1037)\", {\n  # Default behaviour\n  out1 <- Rscript(shQuote(c(\"--vanilla\", \"-e\", \"rlang::inform('foo')\")))\n  out2 <- Rscript(shQuote(c(\n    \"--vanilla\",\n    \"-e\",\n    \"rlang::with_interactive(rlang::inform('foo'))\"\n  )))\n  expect_equal(out1$out, \"foo\")\n  expect_equal(out1$out, out2$out)\n\n  # Sinked behaviour\n  out1 <- Rscript(shQuote(c(\n    \"--vanilla\",\n    \"-e\",\n    \"capture.output(rlang::inform('foo'))\"\n  )))\n  out2 <- Rscript(shQuote(c(\n    \"--vanilla\",\n    \"-e\",\n    \"rlang::with_interactive(capture.output(rlang::inform('foo')))\"\n  )))\n  expect_equal(out1$out, c(\"foo\", \"character(0)\"))\n  expect_equal(out1$out, out2$out)\n})"

const rtdal005999Source0021 = "test_that(\"`inform()` and `warn()` with recurrent footer handle newlines correctly\", {\n  expect_snapshot({\n    inform(\n      \"foo\",\n      .frequency = \"regularly\",\n      .frequency_id = as.character(runif(1))\n    )\n    inform(\n      \"bar\",\n      .frequency = \"regularly\",\n      .frequency_id = as.character(runif(1))\n    )\n\n    warn(\n      \"foo\",\n      .frequency = \"regularly\",\n      .frequency_id = as.character(runif(1))\n    )\n    warn(\n      \"bar\",\n      .frequency = \"regularly\",\n      .frequency_id = as.character(runif(1))\n    )\n  })\n})"

const rtdal005999Source0022 = "test_that(\"`warning.length` is increased (#1211)\", {\n  code <- 'rlang::with_interactive(rlang::abort(paste0(strrep(\"_\", 1000), \"foo\")))'\n  out <- Rscript(shQuote(c(\"--vanilla\", \"-e\", code)))\n  expect_true(any(grepl(\"foo\", out$out)))\n\n  code <- 'rlang::with_interactive(rlang::warn(paste0(strrep(\"_\", 1000), \"foo\")))'\n  out <- Rscript(shQuote(c(\"--vanilla\", \"-e\", code)))\n  expect_true(any(grepl(\"foo\", out$out)))\n\n  # Messages are not controlled by `warning.length`\n  code <- 'rlang::inform(paste0(strrep(\"_\", 1000), \"foo\"))'\n  out <- Rscript(shQuote(c(\"--vanilla\", \"-e\", code)))\n  expect_true(any(grepl(\"foo\", out$out)))\n})"

const rtdal005999Source0023 = `test_that("interrupt() doesn't fail when interrupts are suspended (#1224)", {
  out <- FALSE

  tryCatch(
    interrupt = identity,
    {
      suspendInterrupts({
        tryCatch(
          interrupt = function(x) stop("interrupt!"),
          interrupt()
        )
        out <- TRUE
      })
      # Make sure suspended interrupt is processed
      interrupt()
    }
  )

  expect_true(out)
})`

