const rtdal006004Source0001 = `test_that("error if dots not used", {
  f <- function(x, y, ...) {
    check_dots_used()
    x + y
  }

  expect_no_error(f(1, 2))
  expect_error(f(1, 2, 3), class = "rlib_error_dots_unused")
  expect_error(f(1, 2, 3, 4, 5), class = "rlib_error_dots_unused")
})`

const rtdal006004Source0002 = `test_that("error if dots not used by another function", {
  g <- function(a = 1, b = 1, ...) {
    a + b
  }
  f <- function(x = 1, ...) {
    check_dots_used()
    x * g(...)
  }

  expect_no_error(f(x = 10, a = 1))

  expect_snapshot(error = TRUE, cnd_class = TRUE, {
    f(x = 10, c = 3)
  })
})`

const rtdal006004Source0003 = `test_that("error if dots named", {
  f <- function(..., xyz = 1) {
    check_dots_unnamed()
  }

  expect_null(f(1))

  expect_no_error(f(xyz = 1))
  expect_no_error(f(1, 2, 3))
  expect_no_error(f(1, 2, 3, xyz = 4))
  expect_error(f(1, 2, 3, xy = 4), class = "rlib_error_dots_named")

  expect_snapshot(error = TRUE, cnd_class = TRUE, {
    f(1, 2, 3, xy = 4, x = 5)
  })
})`

const rtdal006004Source0004 = `test_that("error if if dots not empty", {
  f <- function(..., xyz = 1) {
    check_dots_empty()
  }
  f0 <- function(..., xyz = 1) {
    check_dots_empty0(...)
  }

  expect_no_error(f(xyz = 1))
  expect_no_error(f0(xyz = 1))

  expect_snapshot(error = TRUE, cnd_class = TRUE, {
    f(xy = 4)
    f0(xy = 4)
  })
})`

const rtdal006004Source0005 = `test_that("can control the action (deprecated)", {
  f <- function(action, check, ..., xyz = 1) {
    check(action = action)
  }

  expect_error(
    f(abort, check_dots_used, xy = 4),
    class = "rlib_error_dots_unused"
  )
  expect_warning(
    f(warn, check_dots_used, xy = 4),
    class = "rlib_error_dots_unused"
  )
  expect_message(
    f(inform, check_dots_used, xy = 4),
    class = "rlib_error_dots_unused"
  )

  expect_error(
    f(abort, check_dots_unnamed, xy = 4),
    class = "rlib_error_dots_named"
  )
  expect_warning(
    f(warn, check_dots_unnamed, xy = 4),
    class = "rlib_error_dots_named"
  )
  expect_message(
    f(inform, check_dots_unnamed, xy = 4),
    class = "rlib_error_dots_named"
  )

  expect_error(
    f(abort, check_dots_empty, xy = 4),
    class = "rlib_error_dots_nonempty"
  )
  expect_warning(
    f(warn, check_dots_empty, xy = 4),
    class = "rlib_error_dots_nonempty"
  )
  expect_message(
    f(inform, check_dots_empty, xy = 4),
    class = "rlib_error_dots_nonempty"
  )
})`

const rtdal006004Source0006 = `test_that("warn if unused dots", {
  safe_median <- function(x, ...) {
    check_dots_used()
    UseMethod("safe_median")
  }
  safe_median.numeric <- function(x, ..., na.rm = TRUE) {
    stats::median(x, na.rm = na.rm)
  }
  expect_no_error(safe_median(1:10))
  expect_no_error(safe_median(1:10, na.rm = TRUE))
  expect_error(safe_median(1:10, y = 1), class = "rlib_error_dots_unused")
})`

const rtdal006004Source0007 = "test_that(\"can supply `error` handler\", {\n  hnd <- function(cnd) warning(cnd)\n\n  f <- function(...) check_dots_empty(error = hnd)\n  expect_silent(f())\n  expect_error(f(foo), class = \"rlib_error_dots_nonempty\")\n\n  f <- function(...) check_dots_used(error = hnd)\n  expect_silent(f())\n  expect_error(f(foo), class = \"rlib_error_dots_unused\")\n\n  f <- function(...) check_dots_unnamed(error = hnd)\n  expect_silent(f(foo))\n  expect_error(f(foo = foo), class = \"rlib_error_dots_named\")\n})"

const rtdal006004Source0008 = `test_that("expression contents are mentioned", {
  f <- function(...) check_dots_empty()

  expect_snapshot(error = TRUE, {
    f("foo")
    f(foo)
    inject(f(!!letters))
    f(a = {
      1
      2
    })
    f(a = toupper(letters))
  })
})`

const rtdal006004Source0009 = `test_that("empty dots error mentions info bullets if any unnamed element", {
  f <- function(...) check_dots_empty()
  expect_snapshot(error = TRUE, {
    f(1)
    f(a = 1)
    f(a = 1, 2)
  })
})`

const rtdal006004Source0010 = `test_that("check_dots_empty() allows trailing missing arg (#1390)", {
  fn <- function(..., a = NULL) check_dots_empty()

  expect_null(fn(a = 1, ))

  expect_snapshot(error = TRUE, cnd_class = TRUE, {
    fn(a = 1, b = )
  })
})`

