const rtdal006005Source0024 = "test_that(\"`...` forwarding shares the promise object\", {\n  inner <- function(...) {\n    env <- environment()\n    list(\n      expr = env_dot_delayed_expr(env, 1),\n      env = env_dot_delayed_env(env, 1)\n    )\n  }\n  outer <- function(...) inner(...)\n\n  caller_env <- current_env()\n  result <- outer(x + y)\n\n  # Shared promise preserves the original expression and environment\n  expect_equal(result$expr, quote(x + y))\n  expect_identical(result$env, caller_env)\n})"

const rtdal006005Source0025 = "test_that(\"`...` forwarding preserves types\", {\n  inner <- function(...) {\n    env <- environment()\n    env_dot_type(env, 1)\n  }\n  outer <- function(...) inner(...)\n\n  expect_equal(outer(x), \"delayed\")\n})"

const rtdal006005Source0026 = "test_that(\"`...` forwarding reflects forced state\", {\n  inner <- function(...) {\n    env <- environment()\n    env_dot_type(env, 1)\n  }\n  outer <- function(...) {\n    force(..1)\n    inner(...)\n  }\n\n  expect_equal(outer(1 + 1), \"forced\")\n})"

const rtdal006005Source0027 = "test_that(\"env_dot_get() works through `...` forwarding\", {\n  inner <- function(...) env_dot_get(environment(), 1)\n  outer <- function(...) inner(...)\n\n  x <- 42\n  expect_equal(outer(x), 42)\n  expect_equal(outer(1 + 1), 2)\n})"

const rtdal006005Source0028 = `test_that("env_dots_length() reflects forwarded count", {
  inner <- function(...) env_dots_length()
  outer <- function(...) inner(...)

  expect_equal(outer(a, b, c), 3L)
})`

const rtdal006005Source0029 = "test_that(\"env_dots_names() preserved through `...` forwarding\", {\n  inner <- function(...) env_dots_names()\n  outer <- function(...) inner(...)\n\n  expect_equal(outer(a = 1, b = 2), c(\"a\", \"b\"))\n  expect_equal(outer(1, b = 2, 3), c(\"\", \"b\", \"\"))\n  expect_null(outer(1, 2, 3))\n})"

const rtdal006005Source0030 = "test_that(\"`...` forwarding across multiple levels\", {\n  level3 <- function(...) {\n    env <- environment()\n    list(\n      type = env_dot_type(env, 1),\n      expr = env_dot_delayed_expr(env, 1),\n      env = env_dot_delayed_env(env, 1)\n    )\n  }\n  level2 <- function(...) level3(...)\n  level1 <- function(...) level2(...)\n\n  caller_env <- current_env()\n  result <- level1(x + y)\n\n  expect_equal(result$type, \"delayed\")\n  expect_equal(result$expr, quote(x + y))\n  expect_identical(result$env, caller_env)\n})"

const rtdal006005Source0031 = "test_that(\"`..N` forwarding creates a new promise layer\", {\n  inner <- function(...) {\n    env <- environment()\n    list(\n      expr = env_dot_delayed_expr(env, 1),\n      env = env_dot_delayed_env(env, 1)\n    )\n  }\n  outer <- function(...) inner(..1)\n\n  result <- outer(x + y)\n\n  # New promise wrapping `..1`, so expr is `..1` and env is outer's frame\n  expect_equal(result$expr, quote(..1))\n  expect_false(identical(result$env, current_env()))\n})"

const rtdal006005Source0032 = "test_that(\"`..N` forwarding can select specific dots\", {\n  inner <- function(...) {\n    env <- environment()\n    list(\n      n = env_dots_length(),\n      expr1 = env_dot_delayed_expr(env, 1),\n      expr2 = env_dot_delayed_expr(env, 2)\n    )\n  }\n  outer <- function(...) inner(..2, ..1)\n\n  result <- outer(a, b)\n  expect_equal(result$n, 2L)\n  expect_equal(result$expr1, quote(..2))\n  expect_equal(result$expr2, quote(..1))\n})"

const rtdal006005Source0033 = "test_that(\"env_dot_get() works through `..N` forwarding\", {\n  inner <- function(...) env_dot_get(environment(), 1)\n  outer <- function(...) inner(..1)\n\n  x <- 42\n  expect_equal(outer(x), 42)\n  expect_equal(outer(1 + 1), 2)\n})"

const rtdal006005Source0034 = "test_that(\"`..N` forwarding with forced outer dot shows delayed for new promise\", {\n  inner <- function(...) {\n    env <- environment()\n    env_dot_type(env, 1)\n  }\n  outer <- function(...) {\n    force(..1)\n    inner(..1)\n  }\n\n  # The new promise wrapping `..1` is itself delayed,\n  # even though the underlying `..1` in outer is forced\n  expect_equal(outer(1 + 1), \"delayed\")\n})"

const rtdal006005Source0035 = "test_that(\"`..N` forwarding across multiple levels\", {\n  level3 <- function(...) {\n    env <- environment()\n    env_dot_type(env, 1)\n  }\n  level2 <- function(...) level3(..1)\n  level1 <- function(...) level2(..1)\n\n  expect_equal(level1(x), \"delayed\")\n})"

