const rtdal006006Source0001 = `test_that("exprs() without arguments creates an empty named list", {
  expect_identical(exprs(), named_list())
})`

const rtdal006006Source0002 = "test_that(\"exprs() captures arguments forwarded with `...`\", {\n  wrapper <- function(...) exprs(...)\n  expect_identical(wrapper(a = 1, foo = bar), list(a = 1, foo = quote(bar)))\n})"

const rtdal006006Source0003 = `test_that("exprs() captures empty arguments", {
  expect_identical(
    exprs(,, .ignore_empty = "none"),
    set_names(list(missing_arg(), missing_arg()), c("", ""))
  )
})`

const rtdal006006Source0004 = `test_that("dots are always named", {
  expect_named(dots_list("foo"), "")
  expect_named(exprs(foo, bar), c("", ""))

  local_lifecycle_silence()
  expect_named(dots_splice("foo", list("bar")), c("", ""))
})`

const rtdal006006Source0005 = `test_that("dots can be spliced", {
  local_lifecycle_silence()

  spliced_dots <- dots_values(!!!list(letters))
  expect_identical(spliced_dots, list(splice(list(letters))))
  expect_identical(list2(!!!list(letters)), list(letters))
  wrapper <- function(...) list2(...)
  expect_identical(wrapper(!!!list(letters)), list(letters))

  local_lifecycle_silence()
  expect_identical(flatten(dots_values(!!!list(letters))), list(letters))
})`

const rtdal006006Source0006 = `test_that("interpolation by value does not guard formulas", {
  expect_identical(dots_values(~1), list(~1))
})`

const rtdal006006Source0007 = `test_that("dots names can be unquoted", {
  expect_identical(dots_values(!!paste0("foo", "bar") := 10), list(foobar = 10))
})`

const rtdal006006Source0008 = "test_that(\"can take forced dots with `allowForced = FALSE`\", {\n  fn <- function(...) {\n    force(..1)\n    captureDots()\n  }\n  expect_identical(\n    fn(a = letters),\n    pairlist(a = list(expr = letters, env = empty_env()))\n  )\n})"

const rtdal006006Source0009 = `test_that("captured dots are only named if names were supplied", {
  fn <- function(...) captureDots()
  expect_null(names(fn(1, 2)))
  expect_identical(names(fn(a = 1, 2)), c("a", ""))
})`

const rtdal006006Source0010 = `test_that("dots_values() handles forced dots", {
  fn <- function(...) {
    force(..1)
    dots_values(...)
  }
  expect_identical(fn("foo"), list("foo"))

  expect_identical(
    lapply(1:2, function(...) dots_values(...)),
    list(list(1L), list(2L))
  )
  expect_identical(lapply(1:2, dots_values), list(list(1L), list(2L)))
})`

const rtdal006006Source0011 = `test_that("empty arguments trigger meaningful error", {
  expect_snapshot(error = TRUE, cnd_class = TRUE, {
    list2(1, , 3)
    dots_list(1, , 3)
  })
})`

const rtdal006006Source0012 = `test_that("cleans empty arguments", {
  expect_identical(dots_list(1, ), named_list(1))
  expect_identical(list2(1, ), list(1))
  expect_identical(exprs(1, ), named_list(1))
  expect_identical(dots_list(, 1, , .ignore_empty = "all"), named_list(1))
})`

const rtdal006006Source0013 = `test_that("doesn't clean named empty argument arguments", {
  expect_error(dots_list(1, a = ), "empty")
  expect_identical(exprs(1, a = ), alist(1, a = ))
  expect_identical(
    exprs(1, a = , b = , , .ignore_empty = "all"),
    alist(1, a = , b = )
  )
})`

const rtdal006006Source0014 = `test_that("capturing dots by value only unquote-splices at top-level", {
  expect_identical_(dots_list(!!!list(quote(!!!a))), named_list(quote(!!!a)))
  expect_identical_(dots_list(!!!exprs(!!!1:3)), named_list(1L, 2L, 3L))
})`

const rtdal006006Source0015 = `test_that("can't unquote when capturing dots by value", {
  expect_identical(dots_list(!!!list(!!!TRUE)), named_list(FALSE))
})`

const rtdal006006Source0016 = `test_that("can splice NULL value", {
  expect_identical(dots_list(!!!NULL), named_list())
  expect_identical(dots_list(1, !!!NULL, 3), named_list(1, 3))
})`

const rtdal006006Source0017 = `test_that("dots_splice() flattens lists", {
  local_lifecycle_silence()
  expect_identical(
    dots_splice(list("a", list("b"), "c"), "d", list("e")),
    named_list("a", list("b"), "c", "d", "e")
  )
  expect_identical(
    dots_splice(list("a"), !!!list("b"), list("c"), "d"),
    named_list("a", "b", "c", "d")
  )
  expect_identical(
    dots_splice(list("a"), splice(list("b")), list("c"), "d"),
    named_list("a", "b", "c", "d")
  )
})`

const rtdal006006Source0018 = `test_that("dots_splice() doesn't squash S3 objects", {
  local_lifecycle_silence()
  s <- structure(list(v1 = 1, v2 = 2), class = "foo")
  expect_identical(dots_splice(s, s), named_list(s, s))
})`

const rtdal006006Source0019 = `test_that("dots_split() splits named and unnamed dots", {
  dots <- dots_split(1, 2)
  expect_identical(dots$named, list())
  expect_identical(dots$unnamed, list(1, 2))

  dots <- dots_split(a = 1, 2)
  expect_identical(dots$named, list(a = 1))
  expect_identical(dots$unnamed, list(2))

  dots <- dots_split(a = 1, b = 2)
  expect_identical(dots$named, list(a = 1, b = 2))
  expect_identical(dots$unnamed, list())
})`

const rtdal006006Source0020 = `test_that("dots_split() handles empty dots", {
  dots <- dots_split()
  expect_identical(dots$named, list())
  expect_identical(dots$unnamed, list())
})`

const rtdal006006Source0021 = `test_that("dots_split() fails if .n_unnamed doesn't match", {
  expect_error(dots_split(1, 2, .n_unnamed = 1), "Expected 1 unnamed")
  expect_error(dots_split(1, 2, .n_unnamed = 0:1), "Expected 0 or 1 unnamed")

  dots <- dots_split(a = 1, 2, .n_unnamed = 1)
  expect_identical(dots$named, list(a = 1))
  expect_identical(dots$unnamed, list(2))
})`

const rtdal006006Source0022 = `test_that("can splice NULL and atomic vectors", {
  expect_identical(list2(!!!letters), as.list(letters))
  expect_identical(list2(!!!NULL), list())
})`

const rtdal006006Source0023 = `test_that("can unquote quosures in LHS", {
  quo <- quo(foo)
  expect_identical(list2(!!quo := NULL), list(foo = NULL))
  expect_identical(exprs(!!quo := bar), exprs(foo = bar))
})`

const rtdal006006Source0024 = `test_that("can preserve empty arguments", {
  list3 <- function(...) unname(dots_list(..., .preserve_empty = TRUE))
  expect_identical(list3(,), list(missing_arg()))
  expect_identical(
    list3(,, .ignore_empty = "none"),
    list(missing_arg(), missing_arg())
  )
  expect_identical(list3(,, .ignore_empty = "all"), list())
})`

const rtdal006006Source0025 = "test_that(\"forced symbolic objects are not evaluated\", {\n  x <- list(quote(`_foo`))\n  expect_identical_(lapply(x, list2), list(x))\n  expect_identical_(list2(!!!x), x)\n\n  x <- unname(exprs(stop(\"tilt\")))\n  expect_identical_(lapply(x, list2), list(x))\n})"

const rtdal006006Source0026 = "test_that(\"dots collectors do not warn by default with bare `<-` arguments\", {\n  expect_no_warning(list2(a <- 1))\n  expect_no_warning(dots_list(a <- 1))\n\n  expect_no_warning(exprs(a <- 1))\n  expect_no_warning(quos(a <- 1))\n\n  myexprs <- function(...) enexprs(...)\n  myquos <- function(...) enexprs(...)\n  expect_no_warning(myexprs(a <- 1))\n  expect_no_warning(myquos(a <- 1))\n})"

const rtdal006006Source0027 = "test_that(\"dots collectors can elect to warn with bare `<-` arguments\", {\n  expect_warning(dots_list(a <- 1, .check_assign = TRUE), \"`<-` as argument\")\n  myexprs <- function(...) enexprs(..., .check_assign = TRUE)\n  myquos <- function(...) enexprs(..., .check_assign = TRUE)\n  expect_warning(myexprs(TRUE, a <- 1), \"`<-` as argument\")\n  expect_warning(myquos(TRUE, a <- 1), \"`<-` as argument\")\n})"

const rtdal006006Source0028 = `test_that("dots collectors never warn for <- when option is set", {
  local_options(rlang_dots_disable_assign_warning = TRUE)

  expect_no_warning(list2(a <- 1))
  myexprs <- function(...) enexprs(..., .check_assign = TRUE)
  myquos <- function(...) enquos(..., .check_assign = TRUE)
  expect_no_warning(myexprs(a <- 1))
  expect_no_warning(myquos(a <- 1))
})`

const rtdal006006Source0029 = "test_that(\"`.homonyms` is matched exactly\", {\n  expect_error(dots_list(.homonyms = \"k\"), \"must be one of\")\n})"

const rtdal006006Source0030 = "test_that(\"`.homonyms = 'first'` matches first homonym\", {\n  list_first <- function(...) {\n    dots_list(..., .homonyms = \"first\")\n  }\n\n  out <- list_first(1, 2)\n  expect_identical(out, named_list(1, 2))\n\n  out <- list_first(a = 1, b = 2, 3, 4)\n  expect_identical(out, list(a = 1, b = 2, 3, 4))\n\n  out <- list_first(a = 1, b = 2, a = 3, a = 4, 5, 6)\n  expect_identical(out, list(a = 1, b = 2, 5, 6))\n})"

const rtdal006006Source0031 = "test_that(\"`.homonyms = 'last'` matches last homonym\", {\n  list_last <- function(...) {\n    dots_list(..., .homonyms = \"last\")\n  }\n\n  out <- list_last(1, 2)\n  expect_identical(out, named_list(1, 2))\n\n  out <- list_last(a = 1, b = 2, 3, 4)\n  expect_identical(out, list(a = 1, b = 2, 3, 4))\n\n  out <- list_last(a = 1, b = 2, a = 3, a = 4, 5, 6)\n  expect_identical(out, list(b = 2, a = 4, 5, 6))\n})"

const rtdal006006Source0032 = "test_that(\"`.homonyms` = 'error' fails with homonyms\", {\n  list_error <- function(...) {\n    dots_list(..., .homonyms = \"error\")\n  }\n\n  expect_identical(list_error(1, 2), named_list(1, 2))\n  expect_identical(list_error(a = 1, b = 2), list(a = 1, b = 2))\n\n  expect_snapshot({\n    (expect_error(list_error(1, a = 2, a = 3)))\n    (expect_error(list_error(1, a = 2, b = 3, 4, b = 5, b = 6, 7, a = 8)))\n    (expect_error(list_error(1, a = 2, b = 3, 4, b = 5, b = 6, 7, a = 8)))\n  })\n})"

const rtdal006006Source0033 = "test_that(\"`.homonyms` works with spliced arguments\", {\n  args <- list(a = 1, b = 2, a = 3, a = 4, 5, 6)\n  expect_identical(\n    dots_list(!!!args, .homonyms = \"first\"),\n    list(a = 1, b = 2, 5, 6)\n  )\n\n  myexprs <- function(...) enexprs(..., .homonyms = \"last\")\n  expect_identical(myexprs(!!!args), list(b = 2, a = 4, 5, 6))\n\n  myquos <- function(...) enquos(..., .homonyms = \"first\")\n  expect_identical(\n    myquos(!!!args),\n    quos_list(a = quo(1), b = quo(2), quo(5), quo(6))\n  )\n})"

