const rtdal006006Source0040 = "test_that(\"`.named` can be `NULL` (default names) or `FALSE` (minimal names)\", {\n  expect_equal(\n    dots_list(.named = FALSE),\n    set_names(list(), \"\")\n  )\n  expect_equal(\n    exprs(.named = FALSE),\n    set_names(list(), \"\")\n  )\n\n  expect_equal(\n    dots_list(.named = NULL),\n    list()\n  )\n  expect_equal(\n    exprs(.named = NULL),\n    list()\n  )\n})"

const rtdal006006Source0041 = "test_that(\"`.homonyms` error is thrown\", {\n  f <- function() dots_list(a = 1, a = 2, .homonyms = \"error\")\n  expect_snapshot((expect_error(f())))\n})"

const rtdal006006Source0042 = "test_that(\"`list2(!!!x)` returns `x` without duplication\", {\n  expect_snapshot({\n    x <- as.list(1:100)\n    with_memory_prof(out <- list2(!!!x))\n    expect_equal(out, as.list(x))\n\n    x <- 1:100 + 0L\n    with_memory_prof(out <- list2(!!!x))\n    expect_equal(out, as.list(x))\n  })\n})"

const rtdal006006Source0043 = `test_that("list2(...) doesn't copy forced promises (#1491)", {
  fn <- function(...) {
    list(...)
    with_memory_prof(list2(...))
  }

  x <- seq_len(1e4) + 0

  expect_snapshot({
    fn(x, x, x, x, x, x)
  })
})`

const rtdal006006Source0044 = `test_that("names are not mutated after splice box early exit", {
  xs <- list(1)

  dots_list(!!!xs, .named = FALSE)
  expect_equal(names(xs), NULL)

  dots_list(!!!xs, .named = TRUE)
  expect_equal(names(xs), NULL)

  dots_list(!!!xs, .named = NULL)
  expect_equal(names(xs), NULL)
})`

