const rtdal006008Source0054 = "test_that(\"deeper `...` chains unwrap correctly for bindings\", {\n  g <- function(x) env_binding_type(environment(), as.name(\"x\"))\n  mid <- function(...) g(...)\n  f <- function(...) { force(..1); mid(...) }\n  expect_equal(f(1 + 1), \"forced\")\n})"

const rtdal006008Source0055 = "test_that(\"deeper `...` chains unwrap correctly for delayed accessors\", {\n  get_expr <- function(x) env_binding_delayed_expr(environment(), as.name(\"x\"))\n  get_env <- function(x) env_binding_delayed_env(environment(), as.name(\"x\"))\n  mid_expr <- function(...) get_expr(...)\n  deep_expr <- function(...) mid_expr(...)\n  mid_env <- function(...) get_env(...)\n  deep_env <- function(...) mid_env(...)\n  e <- current_env()\n  expect_equal(deep_expr(x + y), quote(x + y))\n  expect_identical(deep_env(x + y), e)\n})"

const rtdal006008Source0056 = "test_that(\"deeper `...` chains unwrap correctly for forced accessor\", {\n  inner <- function(x) env_binding_forced_expr(environment(), as.name(\"x\"))\n  mid <- function(...) inner(...)\n  f <- function(...) { force(..1); mid(...) }\n  foo <- 1\n  expect_equal(f(foo), quote(foo))\n})"

const rtdal006008Source0057 = "test_that(\"env_syms() returns list of symbols\", {\n  e <- env(a = 1, b = 2, c = 3, `.__hidden__.` = 4)\n  syms <- env_syms(e)\n\n  expect_type(syms, \"list\")\n  expect_length(syms, 4L)\n  expect_true(all(map_lgl(syms, is_symbol)))\n  expect_setequal(\n    map_chr(syms, as_string),\n    c(\"a\", \"b\", \"c\", \".__hidden__.\")\n  )\n})"

const rtdal006008Source0058 = `test_that("env_syms() returns empty list for empty env", {
  expect_identical(env_syms(env()), list())
})`

