const rtdal006013Source0001 = `test_that("always returns single string", {
  out <- expr_text(quote({
    a + b
  }))
  expect_length(out, 1)
})`

const rtdal006013Source0002 = `test_that("can truncate lines", {
  out <- expr_text(
    quote({
      a + b
    }),
    nlines = 2
  )
  expect_equal(out, "{\n...")
})`

const rtdal006013Source0003 = `test_that("quotes strings", {
  expect_equal(expr_label("a"), '"a"')
  expect_equal(expr_label("\n"), '"\\n"')
})`

const rtdal006013Source0004 = "test_that(\"backquotes names\", {\n  expect_equal(expr_label(quote(x)), \"`x`\")\n})"

const rtdal006013Source0005 = `test_that("converts atomics to strings", {
  expect_equal(expr_label(0.5), "0.5")
})`

const rtdal006013Source0006 = "test_that(\"expr_label() truncates blocks\", {\n  expect_identical(\n    expr_label(quote({\n      a + b\n    })),\n    \"`{ ... }`\"\n  )\n  expect_identical(\n    expr_label(expr(function() {\n      a\n      b\n    })),\n    \"`function() ...`\"\n  )\n})"

const rtdal006013Source0007 = "test_that(\"expr_label() truncates long calls\", {\n  long_call <- quote(foo())\n  long_arg <- quote(longlonglonglonglonglonglonglonglonglonglonglong)\n  long_call[c(2, 3, 4)] <- list(long_arg, long_arg, long_arg)\n  expect_identical(expr_label(long_call), \"`foo(...)`\")\n})"

const rtdal006013Source0008 = `test_that("expr_label() NULL values come out as expected", {
  expect_identical(expr_label(NULL), "NULL")
})`

const rtdal006013Source0009 = `test_that("expr_name() with symbols, calls, and literals", {
  expect_identical(expr_name(quote(foo)), "foo")
  expect_identical(expr_name(quote(foo(bar))), "foo(bar)")
  expect_identical(expr_name(1L), "1")
  expect_identical(expr_name("foo"), "foo")
  expect_identical(expr_name(function() NULL), "function () ...")
  expect_identical(
    expr_name(expr(function() {
      a
      b
    })),
    "function() ..."
  )
  expect_identical(expr_name(NULL), "NULL")
  expect_error(expr_name(1:2), "must be")
  expect_error(expr_name(env()), "must be")
})`

const rtdal006013Source0010 = `test_that("get_expr() supports closures", {
  expect_true(TRUE)
  return("Disabled because causes dplyr to fail")
  expect_identical(get_expr(identity), quote(x))
})`

const rtdal006013Source0011 = `test_that("set_expr() supports closures", {
  fn <- function(x) x
  expect_equal(set_expr(fn, quote(y)), function(x) y)
})`

const rtdal006013Source0012 = `test_that("expressions are deparsed and printed", {
  expect_output(expr_print(1:2), "<int: 1L, 2L>")
  expect_identical(expr_deparse(1:2), "<int: 1L, 2L>")
})`

const rtdal006013Source0013 = `test_that("imaginary numbers with real part are not syntactic", {
  expect_true(is_syntactic_literal(0i))
  expect_true(is_syntactic_literal(1i))
  expect_true(is_syntactic_literal(na_cpl))
  expect_false(is_syntactic_literal(1 + 1i))
})`

const rtdal006013Source0014 = `test_that("is_expression() detects non-parsable parse trees", {
  expect_true(is_expression(quote(foo(bar = baz(1, NULL)))))
  expect_false(is_expression(expr(foo(bar = baz(!!(1:2), NULL)))))
  expect_false(is_expression(call2(identity)))
})`

const rtdal006013Source0015 = `test_that("is_expression() supports missing arguments", {
  expect_false(is_expression(missing_arg()))
  expect_false(is_expression(quote(foo(,))))
})`

const rtdal006013Source0016 = `test_that("is_expression() supports quoted functions (#1499)", {
  expect_true(is_expression(parse_expr("function() NULL")))
})`

const rtdal006013Source0017 = `test_that("is_expression() detects attributes (#1475)", {
  x <- structure(quote(foo()), attr = TRUE)
  expect_false(is_expression(x))
  expect_false(is_expression(expr(call(!!x))))
  expect_true(is_expression(quote({
    NULL
  })))
  expect_true(is_expression(quote(function() {
    NULL
  })))
})`

const rtdal006013Source0018 = `test_that("arrays are not syntactic", {
  expect_false(is_syntactic_literal(array(1)))
})`

const rtdal006013Source0019 = `test_that("factors are not syntactic", {
  expect_false(is_syntactic_literal(factor("x")))
})`

const rtdal006013Source0020 = `test_that("negative numbers are not syntactic", {
  expect_false(is_syntactic_literal(-1))
  expect_false(is_syntactic_literal(-1L))
  expect_false(is_syntactic_literal(-1i))
})`

const rtdal006013Source0021 = `test_that("NA + 1i is not syntactic", {
  skip_if_not_installed("base", "4.4")
  expect_false(is_syntactic_literal(NA + 1i))
  expect_false(is_syntactic_literal(NA - 1i))
})`

