const rtdal006021Source0059 = `test_that("ensym() unwraps quosures", {
  fn <- function(arg) ensym(arg)
  expect_identical(fn(!!quo(foo)), quote(foo))
  expect_identical(fn(!!quo("foo")), quote(foo))
  expect_snapshot(err(fn(!!quo(foo()))))
})`

const rtdal006021Source0060 = `test_that("ensyms() unwraps quosures", {
  fn <- function(...) ensyms(...)
  expect_identical(fn(!!!quos(foo, "bar")), exprs(foo, bar))
  expect_snapshot(err(fn(!!!quos(foo, bar()))))
})`

const rtdal006021Source0061 = `test_that("enquo0() and enquos0() capture arguments without injection", {
  fn <- function(arg) enquo0(arg)
  expect_equal(
    fn(foo(!!1)),
    quo(foo(!!quote(!!1)))
  )

  fn <- function(...) enquos0(...)
  expect_equal_(
    fn(x = foo(!!1), !!!1:3, z = 3),
    list(x = quo(foo(!!quote(!!1))), quo(!!quote(!!!1:3)), z = quo(3))
  )
})`

const rtdal006021Source0062 = `test_that("enquo0() and enquos0() don't rewrap quosures", {
  fn <- function(arg) enquo0(arg)
  quo <- local(quo(x))
  expect_equal(fn(!!quo), quo)

  fn <- function(...) enquos0(...)
  quo <- local(quo(x))
  expect_equal(fn(!!quo), list(quo))
})`

const rtdal006021Source0063 = `test_that("enquo() defuses numbered dots (#1137)", {
  f <- function(arg) enquo(..1)
  expect_error(
    f(foo),
    "'...' used in an incorrect context"
  )

  f <- function(...) enquo(..1)
  expect_error(
    f(),
    "fewer than 1"
  )

  f <- function(...) enquo(..2)
  expect_error(
    f(1),
    "fewer than 2"
  )
})`

const rtdal006021Source0064 = `test_that("enquos() defuses numbered dots (#1137)", {
  f <- function(...) enquos(...)
  g <- function(...) f(..1)
  expect_equal(
    g(foo),
    quos(foo)
  )

  f <- function(...) enquos(...)
  g <- function(...) f(..1, ..2)
  h <- function(...) g(..1, ...)
  expect_equal(
    h(foo, bar),
    quos(foo, foo)
  )

  g <- function(...) f(..1, ..3)
  expect_equal(
    h(foo, bar),
    quos(foo, bar)
  )

  g <- function(...) f(..1, ..4)
  expect_error(
    h(foo, bar),
    "fewer than 4 elements"
  )
})`

const rtdal006021Source0065 = "test_that(\"`defer()` does not crash with environments containing quosures (#1085)\", {\n  f <- function() {\n    withr::defer(2)\n    dots <- quos(integer(1))\n    quo(c(!!!dots))\n  }\n  expect_no_error(f()) # No crash\n})"

const rtdal006021Source0066 = `test_that("auto-named expressions can be unique-repaired", {
  dots_names <- function(...) {
    dots <- enquos(...)
    dots <- exprs_auto_name(dots, repair_auto = "unique")
    names(dots)
  }

  expect_snapshot({
    expect_equal(
      dots_names(1, foo = 1, 1, foo = 2),
      c("1...1", "foo", "1...3", "foo")
    )

    expect_equal(
      dots_names(bar, foo = 1, bar, foo = 2),
      c("bar...1", "foo", "bar...3", "foo")
    )
  })
})`

const rtdal006021Source0067 = `test_that("can capture forced numbered dot", {
  fn <- function(..., x = ..1) {
    force(x)
    enquo(x)
  }
  expect_equal(fn(1 + 1), quo(2))
})`

const rtdal006021Source0068 = `test_that("enquo() returns literal when ..N chain hits forced promise", {
  inner <- function(...) enquo(..1)
  outer <- function(...) {
    force(..1)
    inner(..1)
  }
  expect_equal(outer(1 + 1), quo(2))

  inner <- function(...) enquos(...)
  outer <- function(...) {
    force(..1)
    inner(..1)
  }
  expect_equal(outer(1 + 1), quos(2))
})`

const rtdal006021Source0069 = `test_that("enquo() returns literal when ..N chain hits value dot", {
  # The compiler unwraps literals from promises, creating DOT_TYPE_value dots
  inner <- function(...) enquo(..1)
  outer <- function(...) inner(..1)
  wrapper <- compiler::cmpfun(function() outer("hello"))
  expect_equal(wrapper(), quo("hello"))

  inner <- function(...) enquos(...)
  outer <- function(...) inner(..1)
  wrapper <- compiler::cmpfun(function() outer("hello"))
  expect_equal(wrapper(), quos("hello"))
})`

const rtdal006021Source0070 = `test_that("enquo() returns missing arg when ..N chain hits missing arg", {
  inner <- function(...) enquo(..1)
  outer <- function(...) inner(..1)
  expect_equal(outer(, 1), quo())

  inner <- function(...) enquos(...)
  outer <- function(...) inner(..1)
  expect_equal(outer(, 1), quos())
})`

const rtdal006021Source0071 = "test_that(\"`enexprs()` and variants support `.named = NULL` (#1223)\", {\n  fn <- function(...) enexprs(..., .named = NULL)\n  expect_equal(fn(), list())\n  expect_equal(fn(1), list(1))\n  expect_equal(fn(x = 1), list(x = 1))\n\n  fn <- function(...) enquos(..., .named = NULL)\n  expect_equal(fn(), unname(quos()))\n  expect_equal(fn(1), unname(quos(1)))\n  expect_equal(fn(x = 1), quos(x = 1))\n})"

const rtdal006021Source0072 = "test_that(\"`.named = NULL` yields `NULL` names (#1505)\", {\n  fn <- function() enquos(.named = NULL)\n  expect_null(names(fn()))\n\n  fn <- function(...) enquos(..., .named = NULL)\n  expect_null(names(fn()))\n  expect_null(names(fn(foo)))\n\n  expect_null(names(quos(.named = NULL)))\n  expect_null(names(quos(foo, .named = NULL)))\n})"

const rtdal006021Source0073 = `test_that("embraced empty arg are detected consistently (#1421)", {
  fn_quos <- function(cond, ...) {
    quos_it({{ cond }}, ...)
  }
  fn_enquos <- function(cond, ...) {
    enquos_it({{ cond }}, ...)
  }

  quos_it <- function(..., .ignore_empty = "all") {
    quos(..., .ignore_empty = .ignore_empty)
  }
  enquos_it <- function(..., .ignore_empty = "all") {
    enquos(..., .ignore_empty = .ignore_empty)
  }

  expect_equal(fn_quos(), quos())
  expect_equal(fn_enquos(), quos())

  expect_equal(fn_quos(.ignore_empty = "trailing"), quos())
  expect_equal(fn_enquos(.ignore_empty = "trailing"), quos())
})`

const rtdal006021Source0074 = "test_that(\"enquos() returns literal values for forced bindings from S3 dispatch (#1886)\", {\n  `+.myclass` <- function(lhs, rhs) {\n    qs <- enquos(lhs, rhs)\n    list(\n      lhs_expr = quo_get_expr(qs[[1]]),\n      rhs_expr = quo_get_expr(qs[[2]]),\n      lhs_env = quo_get_env(qs[[1]]),\n      rhs_env = quo_get_env(qs[[2]])\n    )\n  }\n\n  a <- structure(1, class = \"myclass\")\n  b <- structure(2, class = \"myclass\")\n\n  out <- a + b\n\n  # Primitive S3 dispatch pre-evaluates arguments via SET_PRVALUE(),\n  # making the bindings forced. Forced bindings have no environment,\n  # so enquos() returns the literal values in empty-env quosures.\n  expect_identical(out$lhs_expr, a)\n  expect_identical(out$rhs_expr, b)\n  expect_identical(out$lhs_env, empty_env())\n  expect_identical(out$rhs_env, empty_env())\n})"

