const rtdal006022Source0032 = "test_that(\"`!!!` doesn't modify spliced inputs by reference\", {\n  x <- 1:3\n  quos(!!!x)\n  expect_identical(x, 1:3)\n\n  x <- as.list(1:3)\n  quos(!!!x)\n  expect_identical(x, as.list(1:3))\n\n  x <- quote({\n    1L\n    2L\n    3L\n  })\n  quos(!!!x)\n  expect_equal(\n    x,\n    quote({\n      1L\n      2L\n      3L\n    })\n  ) # equal because of srcrefs\n})"

