const rtdal006022Source0034 = "test_that(\"!!! fails with non-vectors\", {\n  expect_error_(exprs(!!!env()), \"not a vector\")\n  expect_error_(exprs(!!!function() NULL), \"not a vector\")\n  expect_error_(exprs(!!!base::c), \"not a vector\")\n  expect_error_(exprs(!!!base::`{`), \"not a vector\")\n  expect_error_(exprs(!!!expression()), \"not a vector\")\n\n  expect_error_(quos(!!!env()), \"not a vector\")\n  expect_error_(quos(!!!function() NULL), \"not a vector\")\n  expect_error_(quos(!!!base::c), \"not a vector\")\n  expect_error_(quos(!!!base::`{`), \"not a vector\")\n  expect_error_(quos(!!!expression()), \"not a vector\")\n\n  expect_error_(expr(list(!!!env())), \"not a vector\")\n  expect_error_(expr(list(!!!function() NULL)), \"not a vector\")\n  expect_error_(expr(list(!!!base::c)), \"not a vector\")\n  expect_error_(expr(list(!!!base::`{`)), \"not a vector\")\n  expect_error_(expr(list(!!!expression())), \"not a vector\")\n\n  expect_error_(list2(!!!env()), \"not a vector\")\n  expect_error_(list2(!!!function() NULL), \"not a vector\")\n  expect_error_(list2(!!!base::c), \"not a vector\")\n  expect_error_(list2(!!!base::`{`), \"not a vector\")\n  expect_error_(list2(!!!expression()), \"not a vector\")\n})"

const rtdal006022Source0035 = `test_that("!!! succeeds with vectors, pairlists and language objects", {
  expect_identical_(exprs(!!!NULL), named_list())
  expect_identical_(exprs(!!!pairlist(1)), named_list(1))
  expect_identical_(exprs(!!!list(1)), named_list(1))
  expect_identical_(exprs(!!!TRUE), named_list(TRUE))
  expect_identical_(exprs(!!!1L), named_list(1L))
  expect_identical_(exprs(!!!1), named_list(1))
  expect_identical_(exprs(!!!1i), named_list(1i))
  expect_identical_(exprs(!!!"foo"), named_list("foo"))
  expect_identical_(exprs(!!!bytes(0)), named_list(bytes(0)))

  expect_identical_(quos(!!!NULL), quos_list())
  expect_identical_(quos(!!!pairlist(1)), quos_list(quo(1)))
  expect_identical_(quos(!!!list(1)), quos_list(quo(1)))
  expect_identical_(quos(!!!TRUE), quos_list(quo(TRUE)))
  expect_identical_(quos(!!!1L), quos_list(quo(1L)))
  expect_identical_(quos(!!!1), quos_list(quo(1)))
  expect_identical_(quos(!!!1i), quos_list(quo(1i)))
  expect_identical_(quos(!!!"foo"), quos_list(quo("foo")))
  expect_identical_(quos(!!!bytes(0)), quos_list(quo(!!bytes(0))))

  expect_identical_(expr(foo(!!!NULL)), quote(foo()))
  expect_identical_(expr(foo(!!!pairlist(1))), quote(foo(1)))
  expect_identical_(expr(foo(!!!list(1))), quote(foo(1)))
  expect_identical_(expr(foo(!!!TRUE)), quote(foo(TRUE)))
  expect_identical_(expr(foo(!!!1L)), quote(foo(1L)))
  expect_identical_(expr(foo(!!!1)), quote(foo(1)))
  expect_identical_(expr(foo(!!!1i)), quote(foo(1i)))
  expect_identical_(expr(foo(!!!"foo")), quote(foo("foo")))
  expect_identical_(expr(foo(!!!bytes(0))), expr(foo(!!bytes(0))))

  expect_identical_(list2(!!!NULL), list())
  expect_identical_(list2(!!!pairlist(1)), list(1))
  expect_identical_(list2(!!!list(1)), list(1))
  expect_identical_(list2(!!!TRUE), list(TRUE))
  expect_identical_(list2(!!!1L), list(1L))
  expect_identical_(list2(!!!1), list(1))
  expect_identical_(list2(!!!1i), list(1i))
  expect_identical_(list2(!!!"foo"), list("foo"))
  expect_identical_(list2(!!!bytes(0)), list(bytes(0)))
})`

const rtdal006022Source0036 = "test_that(\"!!! calls `[[`\", {\n  as_quos_list <- function(x, env = empty_env()) {\n    new_quosures(map(x, new_quosure, env = env))\n  }\n\n  exp <- map(seq_along(mtcars), function(i) mtcars[[i]])\n  names(exp) <- names(mtcars)\n  expect_identical_(exprs(!!!mtcars), exp)\n  expect_identical_(quos(!!!mtcars), as_quos_list(exp))\n  expect_identical_(expr(foo(!!!mtcars)), do.call(call, c(list(\"foo\"), exp)))\n  expect_identical_(list2(!!!mtcars), as.list(mtcars))\n\n  fct <- factor(c(\"a\", \"b\"))\n  fct <- set_names(fct, c(\"x\", \"y\"))\n  exp <- set_names(list(fct[[1]], fct[[2]]), names(fct))\n  expect_identical_(exprs(!!!fct), exp)\n  expect_identical_(quos(!!!fct), as_quos_list(exp))\n  expect_identical_(expr(foo(!!!fct)), do.call(call, c(list(\"foo\"), exp)))\n  expect_identical_(list2(!!!fct), exp)\n})"

