const rtdal006029Source0006 = "test_that(\"pnf error is validated\", {\n  # No need to revalidate unless we export it\n  expect_true(TRUE)\n  return()\n\n  expect_pnf <- function(out, pkg, ver) {\n    expect_s3_class(out, \"rlib_error_package_not_found\")\n    expect_equal(out$pkg, pkg)\n    expect_equal(out$version, ver)\n  }\n  expect_pnf(new_error_package_not_found(\"foo\"), \"foo\", NULL)\n  expect_pnf(new_error_package_not_found(\"foo\", \"1.0\"), \"foo\", \"1.0\")\n  expect_pnf(\n    new_error_package_not_found(c(\"foo\", \"bar\"), c(\"1.0\", \"1.0\")),\n    c(\"foo\", \"bar\"),\n    c(\"1.0\", \"1.0\")\n  )\n\n  expect_error(\n    new_error_package_not_found(chr()),\n    \"at least one package\"\n  )\n  expect_error(\n    new_error_package_not_found(c(\"foo\", \"bar\"), \"1.0\"),\n    \"as long as `pkg`\"\n  )\n})"

const rtdal006029Source0007 = "test_that(\"can handle check-installed\", {\n  local_interactive()\n\n  # Override `is_installed()` results\n  override <- NULL\n  is_installed_hook <- function(pkg, ver, cmp) {\n    if (is_bool(override)) {\n      rep_along(pkg, override)\n    } else {\n      with_options(\n        \"rlang:::is_installed_hook\" = NULL,\n        is_installed(pkg, version = ver, compare = cmp)\n      )\n    }\n  }\n  local_options(\"rlang:::is_installed_hook\" = is_installed_hook)\n\n  test_env <- current_env()\n  handle <- function(value, frame, expr) {\n    withCallingHandlers(\n      rlib_error_package_not_found = function(cnd) {\n        override <<- value\n        if (!is_null(findRestart(\"rlib_restart_package_not_found\"))) {\n          invokeRestart(\"rlib_restart_package_not_found\")\n        }\n      },\n      expr\n    )\n  }\n\n  override <- NULL\n  expect_no_error(\n    handle(\n      TRUE,\n      test_env,\n      check_installed(c(\"foo\", \"bar\"), version = c(\"1.0\", \"2.0\"))\n    )\n  )\n\n  override <- NULL\n  expect_error(\n    handle(\n      FALSE,\n      test_env,\n      check_installed(c(\"foo\", \"bar\"), version = c(\"1.0\", \"2.0\"))\n    ),\n    \"are required\"\n  )\n})"

const rtdal006029Source0008 = "test_that(\"`pkg` is type-checked\", {\n  expect_snapshot(error = TRUE, cnd_class = TRUE, {\n    is_installed(1)\n    is_installed(na_chr)\n    check_installed(c(\"foo\", \"\"))\n    check_installed(c(\"foo\", \"bar\"), version = c(\"1\", \"\"))\n  })\n})"

const rtdal006029Source0009 = `test_that("pkg_version_info() parses info", {
  local_error_call(call("caller"))

  pkg <- c("foo (>= 1.0)", "bar", "baz (> 3.0)", "pkg (== 2.1)")
  out <- pkg_version_info(pkg, NULL)

  expect_equal(
    out,
    data_frame(
      pkg = c("foo", "bar", "baz", "pkg"),
      cmp = c(">=", NA, ">", "=="),
      ver = c("1.0", NA, "3.0", "2.1")
    )
  )

  pkg <- c("foo (>= 1.0)", "bar", "baz (> 3.0)", "quux", "dplyr (== 2.1)")
  out <- pkg_version_info(pkg, c(NA, "2.0", NA, NA, NA))

  expect_equal(
    out,
    data_frame(
      pkg = c("foo", "bar", "baz", "quux", "dplyr"),
      cmp = c(">=", ">=", ">", NA, "=="),
      ver = c("1.0", "2.0", "3.0", NA, "2.1")
    )
  )

  pkg <- c("foo (>= 1.0)", "bar", "baz (> 3.0)", "quux", "shiny (== 3.0)")
  out <- pkg_version_info(pkg, c(NA, "2.0", NA, "4.0", NA))

  expect_equal(
    out,
    data_frame(
      pkg = c("foo", "bar", "baz", "quux", "shiny"),
      cmp = c(">=", ">=", ">", ">=", "=="),
      ver = c("1.0", "2.0", "3.0", "4.0", "3.0")
    )
  )

  expect_snapshot(error = TRUE, cnd_class = TRUE, {
    pkg_version_info("foo (1.0)")
    pkg_version_info("foo (>= 1.0)", "1.0")
    pkg_version_info(c("foo (!= 1.0)"))
  })
})`

const rtdal006029Source0010 = "test_that(\"pkg_version_info() supports `cmp`\", {\n  local_error_call(call(\"caller\"))\n\n  pkg <- c(\"foo\", \"bar\", \"baz\", \"shiny\")\n  out <- pkg_version_info(\n    pkg,\n    c(\"1.0\", \"2.0\", \"3.0\", \"3.1\"),\n    c(NA, NA, \"<\", \"==\")\n  )\n\n  expect_equal(\n    out,\n    data_frame(\n      pkg = c(\"foo\", \"bar\", \"baz\", \"shiny\"),\n      cmp = c(\">=\", \">=\", \"<\", \"==\"),\n      ver = c(\"1.0\", \"2.0\", \"3.0\", \"3.1\")\n    )\n  )\n\n  expect_snapshot(error = TRUE, cnd_class = TRUE, {\n    pkg_version_info(c(\"foo\", \"bar\", \"baz\"), NULL, c(NA, NA, \">=\"))\n    pkg_version_info(c(\"foo\", \"bar\", \"baz\"), c(\"1\", \"2\", NA), c(NA, NA, \">=\"))\n    pkg_version_info(c(\"foo\", \"bar (>= 2.0)\"), c(NA, \"2.0\"), c(NA, \">=\"))\n    pkg_version_info(\"foo\", \"1.0\", \"!=\")\n    pkg_version_info(\"bar (== 1.0)\", \"1.0\", \"==\")\n  })\n})"

