const rtdal006029Source0013 = `test_that("is_installed('base') works (#1434)", {
  r_ver <- as.character(getRversion())

  expect_true(is_installed("base"))
  expect_true(is_installed("base", version = "0.0.1"))
  expect_true(is_installed("base", version = r_ver))
  expect_false(is_installed("base", version = "999.9.9"))

  skip_if_not(is_string(Sys.getenv("R_DEFAULT_PACKAGES"), ""))

  for (pkg in peek_option("defaultPackages")) {
    expect_true(is_installed(pkg))
    expect_true(is_installed(pkg, version = "0.0.1"))
    expect_true(is_installed(pkg, version = r_ver))
    expect_false(is_installed(pkg, version = "999.9.9"))
  }
})`

const rtdal006029Source0014 = "test_that(\"is_installed() allows irregular package names\", {\n  # Consistently with `loadNamespace()`\n  expect_false(is_installed(\"foo 1.0\"))\n  expect_false(is_installed(\"::\", version = \"1.0\"))\n})"

const rtdal006029Source0015 = `test_that("check_installed() and is_installed() support character vectors", {
  expect_true(is_installed(chr()))
  expect_null(check_installed(chr()))
})`

const rtdal006029Source0016 = `test_that("is_installed() works with pkgload-loaded packages", {
  local_package(name = "rlangtestpkg")
  expect_true(is_installed("rlangtestpkg"))
})`

