const rtdal006030Source0001 = `test_that("can return from frame", {
  fn <- function() {
    val <- g()
    paste(val, "to fn()")
  }
  g <- function(env) {
    h(environment())
    stop("g!\n")
  }
  h <- function(env) {
    return_from(env, "returned from h()")
    stop("h!\n")
  }

  expect_equal(fn(), "returned from h() to fn()")
})`

const rtdal006030Source0002 = `test_that("current_env() and current_fn() return current frame props", {
  fn <- function() {
    list(
      rlang = list(identity(current_env()), current_fn()),
      base = list(environment(), sys.function())
    )
  }
  out <- fn()
  expect_identical(out$rlang[[1]], out$base[[1]])
  expect_identical(out$rlang[[2]], out$base[[2]])
})`

const rtdal006030Source0003 = `test_that("sys_parents() removes infloop values", {
  f <- function() g()
  g <- function() sys_parents()

  parents <- do.call("f", list(), envir = env())
  n <- length(parents)

  # No loop when called in non-frame env
  expect_false(any(parents == seq_len(n)))

  # g() is called by f() which is called by global because the calling
  # env is not on the stack
  expect_equal(parents[[n - 1]], 0) # f()
  expect_equal(parents[[n]], n - 1) # g()
})`

const rtdal006030Source0004 = "test_that(\"current_fn() and caller_fn() work\", {\n  f <- function(n) identity(g(n))\n  g <- function(n) identity(h(n))\n  h <- function(n) identity(caller_fn(n))\n  expect_equal(f(1), g)\n  expect_equal(f(2), f)\n\n  # Need to break the chain of callers to get `NULL` at `n = 3`.\n  # Otherwise we get the `eval()` frame from testthat\n  expect_null(eval_bare(quote(f(3)), env()))\n\n  f <- function() current_fn()\n  expect_equal(f(), f)\n})"

const rtdal006030Source0005 = `test_that("Parents are matched to youngest duplicate frames", {
  skip_on_cran()

  out <- env()
  f <- function() {
    invisible(g(environment(), report("f")))
  }
  g <- function(env, arg) {
    fn <- function() h(env, arg)
    eval(as.call(list(fn)), env)
  }
  h <- function(env, arg) {
    fn <- function() list(arg, report("h"))
    eval(as.call(list(fn)), env)
  }
  report <- function(what) {
    parents <- sys_parents(match_oldest = FALSE)
    env_poke(out, what, parents)
  }

  f()
  f_parents <- tail(out[["f"]], 10) - length(out[["f"]]) + 10
  h_parents <- tail(out[["h"]], 10) - length(out[["h"]]) + 10

  expect_equal(f_parents, c(0:8, 1L))
  expect_equal(h_parents, 0:9)
})`

const rtdal006030Source0006 = `test_that("frame_fn() returns the function of the supplied frame", {
  f <- function() {
    identity(g(current_env()))
  }
  g <- function(frame) {
    identity(h(frame))
  }
  h <- function(frame) {
    tryCatch(frame_fn(frame))
  }
  expect_equal(f(), f)

  f <- function() {
    evalq(g(current_env()))
  }
  expect_equal(f(), f)

  f <- function() {
    evalq(g(current_env()), env())
  }
  eval_prim <- eval(call2(sys.function))
  expect_equal(f(), eval_prim)

  f <- function() {
    eval_bare(quote(g(current_env())), env())
  }
  expect_null(f())
})`

const rtdal006030Source0007 = "test_that(\"current_call(), caller_call() and frame_call() work\", {\n  expect_null(eval_bare(call2(current_call), global_env()))\n  expect_null(eval_bare(call2(caller_call), global_env()))\n  expect_null(eval_bare(call2(frame_call), global_env()))\n\n  f <- function() g()\n  g <- function() {\n    direct <- frame_call()\n    indirect <- evalq(frame_call())\n    expect_equal(direct, indirect)\n  }\n  f()\n\n  f <- function() {\n    this <- current_call()\n    that <- g()\n    expect_equal(this, quote(f()))\n    expect_equal(this, that)\n  }\n  g <- function() caller_call()\n  f()\n\n  return(\"Don't make this guarantee to stay consistent with `caller_env()`\")\n  f <- function() g()\n  g <- function() {\n    direct <- caller_call()\n    indirect <- h(current_env())\n    expect_equal(indirect, direct)\n  }\n  h <- function(env) evalq(caller_call(), env)\n  f()\n})"

const rtdal006030Source0008 = `test_that("caller_env2() respects invariant", {
  f <- function() h()
  h <- function() {
    indirect <- evalq(caller_env2())
    direct <- caller_env2()
    expect_equal(indirect, direct)
  }
  f()

  f <- function() g()
  g <- function() inject(caller_env2(), env())
  expect_equal(f(), global_env())
})`

