const rtdal006032Source0001 = "test_that(\"can parse versions\", {\n  out <- .rlang_downstream_parse_deps(c(\"foo (>= 1.0)\"))\n  expect_equal(\n    out,\n    list(\n      c(pkg = \"foo\", min = \"1.0\")\n    )\n  )\n\n  out <- .rlang_downstream_parse_deps(c(\"foo (>= 1.0)\", \"bar (>= 2.0.0)\"))\n  expect_equal(\n    out,\n    list(\n      c(pkg = \"foo\", min = \"1.0\"),\n      c(pkg = \"bar\", min = \"2.0.0\")\n    )\n  )\n\n  expect_error(\n    .rlang_downstream_parse_deps(\"foo\"),\n    \"Parsing error\"\n  )\n  expect_error(\n    .rlang_downstream_parse_deps(\"foo (1.0)\"),\n    \"Parsing error\"\n  )\n  expect_error(\n    .rlang_downstream_parse_deps(\"foo (< 1.0)\"),\n    \"Can only check `>=` requirements\"\n  )\n})"

const rtdal006032Source0002 = `test_that("can check downstream versions", {
  local_interactive(FALSE)

  ok_deps <- .rlang_downstream_parse_deps(c(
    "base (>= 1.0)",
    "utils (>= 1.1)"
  ))
  expect_no_warning(
    expect_true(
      .rlang_downstream_check(
        pkg = "rlang",
        pkg_ver = "0.5.0",
        deps = ok_deps,
        info = "Consequences.",
        env = env(checked = FALSE)
      )
    )
  )

  bad_deps <- .rlang_downstream_parse_deps(c(
    "base (>= 1.0)",
    "utils (>= 100.10)"
  ))
  expect_snapshot({
    (expect_warning({
      expect_false(
        .rlang_downstream_check(
          pkg = "rlang",
          pkg_ver = "0.5.0",
          deps = bad_deps,
          info = "Consequences.",
          env = env(checked = FALSE)
        )
      )
      NULL
    }))
  })

  missing_deps <- .rlang_downstream_parse_deps(c(
    "base (>= 1.0)",
    "foobar (>= 100.10)"
  ))
  expect_no_warning({
    expect_true(
      .rlang_downstream_check(
        pkg = "rlang",
        pkg_ver = "0.5.0",
        deps = missing_deps,
        info = "Consequences.",
        env = env(checked = FALSE)
      )
    )
    NULL
  })
})`

const rtdal006032Source0003 = "test_that(\"setting `rlib_downstream_check` disables the check\", {\n  local_options(rlib_downstream_check = FALSE)\n  local_interactive(FALSE)\n\n  bad_deps <- .rlang_downstream_parse_deps(c(\n    \"base (>= 1.0)\",\n    \"utils (>= 100.10)\"\n  ))\n  expect_no_warning(\n    expect_null(\n      .rlang_downstream_check(\n        pkg = \"rlang\",\n        pkg_ver = \"0.5.0\",\n        deps = bad_deps,\n        info = \"Consequences.\",\n        env = env(checked = FALSE)\n      )\n    )\n  )\n})"

const rtdal006032Source0004 = `test_that("check_downstream() saves status in global env", {
  local_interactive(TRUE)
  local_options("rlang:::no_downstream_prompt" = TRUE)

  bad_deps <- .rlang_downstream_parse_deps(c(
    "base (>= 1.0)",
    "utils (>= 100.10)"
  ))

  key <- as.character(runif(1))
  check <- function() {
    .rlang_downstream_check(
      pkg = "rlang",
      pkg_ver = "0.5.0",
      deps = bad_deps,
      info = "Consequences.",
      deps_key = key,
      env = env(checked = FALSE)
    )
  }

  expect_warning(expect_false(check()))
  expect_no_warning(expect_null(check()))
})`

