const rtdal006034Source0001 = `test_that("map functions work", {
  expect_equal(map(1:2, length), list(1, 1))
  expect_equal(walk(1:2, length), 1:2)

  expect_equal(map_lgl(0:1, as.logical), c(FALSE, TRUE))
  expect_identical(map_int(1:2, as.integer), 1:2)
  expect_identical(map_dbl(1:2, as.integer), c(1, 2))
  expect_equal(map_chr(1:2, as.character), c("1", "2"))
})`

const rtdal006034Source0002 = "test_that(\"map2 functions work\", {\n  expect_equal(map2(1, 1:2, `+`), list(2, 3))\n\n  expect_equal(map2_lgl(1, 1:2, `==`), c(TRUE, FALSE))\n  expect_identical(map2_int(1, 1:2, `+`), c(2L, 3L))\n  expect_identical(map2_dbl(1, 1:2, `+`), c(2, 3))\n  expect_equal(map2_chr(1, 1:2, paste0), c(\"11\", \"12\"))\n})"

const rtdal006034Source0003 = `test_that("imap works", {
  expect_equal(imap(c("a", "b"), list), list(list("a", 1L), list("b", 2L)))
  expect_equal(
    imap(c(x = "a", y = "b"), list),
    list(x = list("a", "x"), y = list("b", "y"))
  )
  expect_equal(
    imap(c(x = "a", "b"), list),
    list(x = list("a", "x"), list("b", ""))
  )
})`

const rtdal006034Source0004 = `test_that("pmap works", {
  expect_equal(pmap(list(1, 1:2), paste0), list("11", "12"))
})`

const rtdal006034Source0005 = `test_that("predicate based functions work", {
  x <- list(1, 2)
  expect_equal(keep(x, ~ sum(.x) > 1), list(2))
  expect_equal(discard(x, ~ sum(.x) > 1), list(1))
  expect_equal(map_if(x, ~ sum(.x) > 1, ~10), list(1, 10))

  expect_true(every(x, ~ .x > 0))
  expect_false(every(x, ~ .x < 0))
  expect_true(some(x, ~ .x > 0))
  expect_false(some(x, ~ .x < 0))

  expect_equal(detect(x, ~ .x > 1), 2)
  expect_identical(detect_index(x, ~ .x > 0), 1L)
})`

const rtdal006034Source0006 = "test_that(\"reduce/accumulate work\", {\n  x <- 1:3\n  expect_equal(reduce(x, `+`), 6)\n  expect_equal(reduce_right(x, `+`), 6)\n\n  expect_equal(accumulate(x, `+`), c(1, 3, 6))\n  expect_equal(accumulate_right(x, `+`), c(6, 5, 3))\n})"

const rtdal006034Source0007 = `test_that("transpose() handles empty list", {
  expect_equal(transpose(list()), list())
})`

const rtdal006034Source0008 = `test_that("transpose() handles incongruent names consistently with purrr (#1346)", {
  x <- list(
    needles = list(a = 1, b = 2),
    condition = c("<", ">")
  )
  expect_equal(
    transpose(x),
    list(
      a = list(needles = 1, condition = "<"),
      b = list(needles = 2, condition = ">")
    )
  )

  x <- list(
    needles = list(a = 1, b = 2),
    condition = c(c = "<", d = ">")
  )
  expect_equal(
    transpose(x),
    list(
      a = list(needles = 1, condition = NULL),
      b = list(needles = 2, condition = NULL)
    )
  )
})`

