const rtdal006038Source0001 = `test_that("data_frame() recycles", {
  expect_equal(
    data_frame(x = 1, y = 1:2),
    data_frame(x = c(1, 1), y = 1:2)
  )

  out <- data_frame(x = list(1), y = 1:2)
  expect_equal(out$x, list(1, 1))
})`

const rtdal006038Source0002 = `test_that("data_frame() nests", {
  df <- data_frame(a = 3:4)
  out <- data_frame(x = 1:2, y = df)
  expect_equal(out$y, df)

  out <- data_frame(x = 1:2, y = data_frame(a = 1))
  expect_equal(out$y, data_frame(a = c(1, 1)))
})`

const rtdal006038Source0003 = "test_that(\"new_data_frame handles zero-length inputs\", {\n  # Zero-length input creates zero-length data frame\n  d <- data_frame(x = numeric(0), y = numeric(0))\n  expect_equal(nrow(d), 0L)\n\n  # Constants are ignored in the context of zero-length input\n  d <- data_frame(x = numeric(0), y = numeric(0), z = 1)\n  expect_equal(nrow(d), 0L)\n\n  # Vectors of length > 1 don't mix with zero-length input\n  expect_error(\n    data_frame(x = numeric(0), y = numeric(0), z = 1, a = c(1, 2)),\n    \"Inputs can't be recycled\"\n  )\n\n  # Explicit recycling doesn't work with zero-length input\n  expect_error(\n    new_data_frame(df_list(x = numeric(0), z = 1, .size = 5)),\n    \"Inputs can't be recycled to `size`.\"\n  )\n\n  # But it works without\n  d <- new_data_frame(df_list(x = 1, y = \"a\", .size = 3))\n  expect_equal(nrow(d), 3L)\n  expect_identical(d$x, rep(1, 3L))\n  expect_identical(d$y, rep(\"a\", 3L))\n\n  # Can supply size for empty df\n  d <- new_data_frame(.size = 3)\n  expect_equal(dim(d), c(3, 0))\n})"

const rtdal006038Source0004 = `test_that("can slice vectors and data frames", {
  fct <- factor(c("a", "b", "a"))
  fct_exp <- factor(c("a", "a"), levels = c("a", "b"))
  expect_equal(
    vec_slice(fct, c(1, 3)),
    fct_exp
  )
  expect_equal(
    vec_init(fct, 2),
    factor(c(NA, NA), c("a", "b"))
  )

  df <- data_frame(
    x = fct,
    y = data_frame(a = list(1, 2, 3))
  )
  df_exp <- data_frame(
    x = fct_exp,
    y = data_frame(a = list(1, 3))
  )
  expect_equal(
    vec_slice(df, c(1, 3)),
    df_exp
  )
  expect_equal(
    vec_init(df, 2),
    data_frame(
      x = vec_init(fct, 2),
      y = data_frame(a = list(NULL, NULL))
    )
  )

  rep_exp <- data_frame(
    x = rep(fct, 2),
    y = data_frame(a = rep(list(1, 2, 3), 2))
  )
  expect_equal(vec_rep(df, 2), rep_exp)
})`

