const rtdal006038Source0020 = "test_that(\"can bind data frames\", {\n  expect_equal(\n    vec_rbind(\n      data.frame(x = 1),\n      data_frame(y = \"\")\n    ),\n    data_frame(x = c(1, NA), y = c(NA, \"\"))\n  )\n\n  expect_equal(\n    vec_cbind(\n      data_frame(x = data_frame(a = TRUE)),\n      data_frame(y = list(\"\"))\n    ),\n    data_frame(x = data_frame(a = TRUE), y = list(\"\"))\n  )\n\n  expect_equal(\n    vec_rbind(\n      data_frame(x = TRUE),\n      data_frame(y = list(\"\"))\n    ),\n    data_frame(x = c(TRUE, NA), y = list(NULL, \"\"))\n  )\n\n  # `rbind()` has trouble binding df-cols on old R versions\n  skip_if(getRversion() < \"4.0\")\n  expect_equal(\n    vec_rbind(\n      data_frame(x = data_frame(a = TRUE)),\n      data_frame(y = list(\"\"))\n    ),\n    data_frame(x = data_frame(a = c(TRUE, NA)), y = list(NULL, \"\"))\n  )\n})"

const rtdal006038Source0021 = `test_that("casting to df type uses same column order", {
  df1 <- data.frame(x = 1, y = 2)
  df2 <- data.frame(y = 3, x = 4)
  expect_equal(
    vec_cast_common(list(df1, df2)),
    list(df1, df2[2:1])
  )

  df1 <- data.frame(y = 2)
  df2 <- data.frame(y = 3, x = 4)
  expect_equal(
    vec_cast_common(list(df1, df2)),
    list(data.frame(y = 2, x = na_dbl), df2)
  )
})`

const rtdal006038Source0022 = `test_that("vec_as_location() works", {
  n <- 4
  names <- letters[1:4]

  i <- c(2, 3)
  expect_identical(vec_as_location(i, n, names), 2:3)

  i <- -c(2, 3)
  expect_identical(vec_as_location(i, n, names), c(1L, 4L))

  i <- c(TRUE, FALSE, TRUE, FALSE)
  expect_identical(vec_as_location(i, n, names), c(1L, 3L))

  i <- c("a", "d")
  expect_identical(vec_as_location(i, n, names), c(1L, 4L))
})`

const rtdal006038Source0023 = `test_that("vec_as_location() recycles scalar logical inputs", {
  expect_equal(vec_as_location(TRUE, 0), int())
  expect_equal(vec_as_location(FALSE, 0), int())
})`

const rtdal006038Source0024 = `test_that("vec_slice() preserves attributes of data frames", {
  df <- data_frame(x = 1:2)
  attr(df, "foo") <- TRUE

  out <- vec_slice(df, 1)
  expect_true(attr(out, "foo"))
})`

const rtdal006038Source0025 = "test_that(\"vec_slice() doesn't restore attributes if there is a `[` method\", {\n  df <- new_data_frame(\n    df_list(x = 1:2),\n    .class = \"rlang_foobar\",\n    foo = \"bar\"\n  )\n  local_methods(`[.rlang_foobar` = function(x, ...) {\n    out <- NextMethod()\n    attr(out, \"foo\") <- \"dispatched\"\n    out\n  })\n\n  expect_equal(\n    attr(vec_slice(df, 1), \"foo\"),\n    \"dispatched\"\n  )\n})"

const rtdal006038Source0026 = `test_that("vec_slice() preserves attributes of vectors", {
  x <- set_names(1:2, c("a", "b"))
  attr(x, "foo") <- TRUE

  out <- vec_slice(x, 1)
  expect_true(attr(out, "foo"))
  expect_equal(attr(out, "names"), "a")
})`

const rtdal006038Source0027 = `test_that("can row-bind unspecified columns", {
  expect_equal(
    vec_rbind(
      data_frame(x = NA),
      data_frame(x = "")
    ),
    data_frame(x = c(NA, ""))
  )
})`

const rtdal006038Source0028 = `test_that("unspecified is detected recursively", {
  ptype <- vec_ptype(data_frame(x = NA))
  expect_s3_class(ptype$x, "rlang_unspecified")
})`

const rtdal006038Source0029 = `test_that("ptype is finalised", {
  x <- data_frame(x = NA)

  out <- vec_cast_common(list(x, x))[[1]]
  expect_identical(out$x, NA)

  out <- vec_cast_common(list(out, x))[[1]]
  expect_identical(out$x, NA)
})`

const rtdal006038Source0030 = "test_that(\"vec_recycle_common() throws appropriate errors\", {\n  expect_error(\n    vec_recycle_common(list(a = 1:2), size = 1),\n    \"Inputs can't be recycled to `size`.\"\n  )\n  expect_error(\n    vec_recycle_common(list(a = 1:2, b = 1:3)),\n    \"Inputs can't be recycled to a common size.\"\n  )\n})"

