const rtdal006039Source0001 = "test_that(\"LHS must be a list of symbols wrapped in `c()`\", {\n  expect_error(\n    foo %<-% list(1),\n    \"must be a call to `c()`\",\n    fixed = TRUE\n  )\n\n  expect_error(\n    c(foo()) %<-% list(1),\n    \"Element 1 of the left-hand side .* must be a symbol\"\n  )\n})"

const rtdal006039Source0002 = `test_that("can assign lists and vectors", {
  c(foo, bar) %<-% list(a = 1, 2)
  expect_equal(list(foo, bar), list(1, 2))

  c(foo, bar) %<-% c(a = 1, 2)
  expect_equal(list(foo, bar), list(1, 2))
})`

const rtdal006039Source0003 = `test_that("RHS and LHS must have the same length", {
  expect_error(
    c(foo) %<-% list(),
    "must be the same length"
  )

  expect_error(
    c(foo, bar) %<-% as.list(1:10),
    "must be the same length"
  )
})`

