const rtdal006040Source0001 = `test_that("names() dispatches on environment", {
  env <- child_env(NULL, foo = "foo", bar = "bar")
  expect_identical(sort(names(env)), c("bar", "foo"))
})`

const rtdal006040Source0002 = `test_that("lazy objects are converted to tidy quotes", {
  env <- child_env(current_env())

  lazy <- structure(list(expr = quote(foo(bar)), env = env), class = "lazy")
  expect_identical(compat_lazy(lazy), new_quosure(quote(foo(bar)), env))

  lazy_str <- "foo(bar)"
  expect_identical(compat_lazy(lazy_str), quo(foo(bar)))

  lazy_lang <- quote(foo(bar))
  expect_identical(compat_lazy(lazy_lang), quo(foo(bar)))

  lazy_sym <- quote(foo)
  expect_identical(compat_lazy(lazy_sym), quo(foo))
})`

const rtdal006040Source0003 = `test_that("lazy_dots objects are converted to tidy quotes", {
  env <- child_env(current_env())

  lazy_dots <- structure(
    class = "lazy_dots",
    list(
      lazy = structure(list(expr = quote(foo(bar)), env = env), class = "lazy"),
      lazy_lang = quote(foo(bar))
    )
  )

  expected <- list(
    lazy = new_quosure(quote(foo(bar)), env),
    lazy_lang = quo(foo(bar)),
    quo(foo(bar))
  )

  expect_identical(
    compat_lazy_dots(lazy_dots, current_env(), "foo(bar)"),
    expected
  )
})`

const rtdal006040Source0004 = "test_that(\"unnamed lazy_dots are given default names\", {\n  lazy_dots <- structure(\n    class = \"lazy_dots\",\n    list(\n      \"foo(baz)\",\n      quote(foo(bar))\n    )\n  )\n\n  expected <- list(\n    `foo(baz)` = quo(foo(baz)),\n    `foo(bar)` = quo(foo(bar)),\n    foobarbaz = quo(foo(barbaz))\n  )\n  dots <- compat_lazy_dots(\n    lazy_dots,\n    current_env(),\n    foobarbaz = \"foo(barbaz)\",\n    .named = TRUE\n  )\n\n  expect_identical(dots, expected)\n})"

const rtdal006040Source0005 = `test_that("compat_lazy() handles missing arguments", {
  expect_identical(compat_lazy(), quo())
})`

const rtdal006040Source0006 = `test_that("compat_lazy_dots() takes lazy objects", {
  lazy <- structure(list(expr = quote(foo), env = empty_env()), class = "lazy")
  expect_identical(
    compat_lazy_dots(lazy),
    named_list(new_quosure(quote(foo), empty_env()))
  )
})`

const rtdal006040Source0007 = `test_that("compat_lazy_dots() takes symbolic objects", {
  expect_identical(
    compat_lazy_dots(quote(foo), empty_env()),
    named_list(new_quosure(quote(foo), empty_env()))
  )
  expect_identical(
    compat_lazy_dots(quote(foo(bar)), empty_env()),
    named_list(new_quosure(quote(foo(bar)), empty_env()))
  )
})`

const rtdal006040Source0008 = `test_that("compat_lazy() demotes character vectors to strings", {
  expect_identical(
    compat_lazy_dots(NULL, current_env(), c("foo", "bar")),
    named_list(as_quosure(~foo))
  )
})`

const rtdal006040Source0009 = `test_that("compat_lazy() handles numeric vectors", {
  expect_identical(
    compat_lazy_dots(NULL, current_env(), NA_real_),
    named_list(set_env(quo(NA_real_)))
  )
  expect_warning(
    expect_identical(
      compat_lazy_dots(NULL, current_env(), 1:3),
      named_list(set_env(quo(1L)))
    ),
    "Truncating vector"
  )
})`

const rtdal006040Source0010 = `test_that("compat_lazy() handles bare formulas", {
  expect_identical(compat_lazy(~foo), quo(foo))
  expect_identical(compat_lazy_dots(~foo), named_list(quo(foo)))
})`

const rtdal006040Source0011 = `test_that("trimws() trims", {
  x <- "  foo.  "
  expect_identical(trimws(x), "foo.")
  expect_identical(trimws(x, "l"), "foo.  ")
  expect_identical(trimws(x, "r"), "  foo.")
})`

const rtdal006040Source0012 = `test_that("map2() sets names", {
  expect_identical(
    map2(list(foo = NULL, bar = NULL), 1:2, function(...) NULL),
    list(foo = NULL, bar = NULL)
  )
})`

const rtdal006040Source0013 = `test_that("map2() discards recycled names", {
  expect_identical(map2(list(foo = NULL), 1:3, function(...) NULL), new_list(3))
})`

