const rtdal006065Source0001 = `paged_table_type_sum <- function(x) {
  #  support vctrs-type vectors if the package is installed
  if (xfun::loadable("vctrs") && vctrs::vec_is(x)) return(vctrs::vec_ptype_abbr(x))
  type_sum <- function(x)
  {
    format_sum <- switch(
      class(x)[[1]], ordered = "ord", factor = "fctr", POSIXt = "dttm",
      difftime = "time", Date = "date", data.frame = class(x)[[1]],
      tbl_df = "tibble", NULL
    )
    if (!is.null(format_sum)) {
      format_sum
    } else if (!is.object(x)) {
      switch(typeof(x),
             logical = "lgl",
             integer = "int",
             double = "dbl",
             character = "chr",
             complex = "cplx",
             closure = "fun",
             environment = "env",
             typeof(x)
      )
    } else if (!isS4(x)) {
      paste0("S3: ", class(x)[[1]])
    } else {
      paste0("S4: ", methods::is(x)[[1]])
    }
  }

  type_sum(x)
}`

const rtdal006065Source0002 = `paged_table_obj_sum <- function(x) {
  big_mark <- function(x, ...) {
    mark <- if (identical(getOption("OutDec"), ",")) "." else ","
    formatC(x, big.mark = mark, ...)
  }

  dim_desc <- function(x) {
    dim <- dim(x) %||% length(x)
    format_dim <- vapply(dim, big_mark, character(1))
    format_dim[is.na(dim)] <- "??"
    paste0(format_dim, collapse = " \u00d7 ")
  }

  is_atomic <- function(x) {
    is.atomic(x) && !is.null(x)
  }

  is_vector <- function(x) {
    is_atomic(x) || is.list(x)
  }

  paged_table_is_vector_s3 <- function(x) {
    switch(class(x)[[1]],
      ordered = TRUE,
      factor = TRUE,
      Date = TRUE,
      POSIXct = TRUE,
      difftime = TRUE,
      data.frame = TRUE,
      !is.object(x) && is_vector(x))
  }

  size_sum <- function(x) {
    if (!paged_table_is_vector_s3(x)) return("")

    paste0(" [", dim_desc(x), "]" )
  }

  obj_sum.default <- function(x) {
    paste0(paged_table_type_sum(x), size_sum(x))
  }

  switch(class(x)[[1]],
         POSIXlt = rep("POSIXlt", length(x)),
         list = vapply(x, obj_sum.default, character(1L)),
         paste0(paged_table_type_sum(x), size_sum(x))
  )
}`

const rtdal006065Source0003 = `paged_table_option <- function(option, options, default = NULL) {
  if (is.null(options))
    options <- list()
  if (!is.null(options[[option]]))
    options[[option]]
  else if (is.null(knitr::opts_current$get(option)))
    getOption(option, default)
  else
    knitr::opts_current$get(option)
}`

const rtdal006065Source0004 = "paged_table_html <- function(x, options = NULL) {\n  addRowNames = paged_table_option(\"rownames.print\", options)\n  addRowNames <- if (is.null(addRowNames)) (.row_names_info(x, type = 1) > 0) else addRowNames\n\n  maxPrint <- paged_table_option(\"max.print\", options, 1000)\n\n  if (\"tbl_sql\" %in% class(x)) {\n    maxPrint <- paged_table_option(\"sql.max.print\", options, 1000)\n  }\n\n  # hard stop at 10K items to print to prevent pandoc from failing\n  maxPrint <- if (maxPrint > 10000) 10000 else maxPrint\n\n  data <- as.data.frame(utils::head(x, maxPrint))\n\n  data <- if (is.null(data)) as.data.frame(list()) else data\n\n  columnNames <- names(data)\n  columnSequence <- seq_len(ncol(data))\n\n  columns <- lapply(\n    columnSequence,\n    function(columnIdx) {\n      column <- data[[columnIdx]]\n      baseType <- class(column)[[1]]\n      tibbleType <- paged_table_type_sum(column)\n\n      list(\n        label = if (!is.null(columnNames)) columnNames[[columnIdx]] else \"\",\n        name = columnIdx,\n        type = tibbleType,\n        align = if (baseType == \"character\" || baseType == \"factor\") \"left\" else \"right\"\n      )\n    }\n  )\n\n  names(data) <- as.character(columnSequence)\n\n  if (addRowNames) {\n    columns <- c(\n      list(\n        list(\n          label = \"\",\n          name = \"_rn_\",\n          type = \"\",\n          align = \"left\"\n        )\n      ),\n      columns\n    )\n\n    data$`_rn_` <- rownames(data)\n  }\n\n  columns <- unname(columns)\n\n  is_list <- vapply(data, is.list, logical(1))\n  data[is_list] <- lapply(data[is_list], function(x) {\n    summary <- paged_table_obj_sum(x)\n    paste0(\"<\", summary, \">\")\n  })\n\n  data <- as.data.frame(\n    lapply(\n      data,\n      function(y) {\n        # escape NAs from character columns\n        if (typeof(y) == \"character\") {\n          y[y == \"NA\"] <- \"__NA__\"\n        }\n\n        y <- encodeString(format(y, digits = getOption(\"digits\")))\n\n        # trim spaces\n        gsub(\"^\\\\s+|\\\\s+$\", \"\", y)\n      }\n    ),\n    stringsAsFactors = FALSE,\n    optional = TRUE)\n\n  rowCount <- paged_table_option(\"rows.print\", options, 10)\n\n  pagedTableOptions <- list(\n    columns = list(\n      min = paged_table_option(\"cols.min.print\", options),\n      max = paged_table_option(\"cols.print\", options, 10)\n    ),\n    rows = list(\n      min = rowCount,\n      max = rowCount\n    ),\n    pages = paged_table_option(\"pages.print\", options)\n  )\n\n  pagedData <- list(\n    columns = columns,\n    data = if (length(data) == 0) list() else data,\n    options = pagedTableOptions\n  )\n\n  paste(\n    \"<div data-pagedtable=\\\"false\\\">\",\n    \"  <script data-pagedtable-source type=\\\"application/json\\\">\",\n    jsonlite::toJSON(pagedData),\n    \"  </script>\",\n    \"</div>\",\n    sep = \"\\n\"\n  )\n}"

const rtdal006065Source0005 = `paged_table <- function(x, options = NULL) {
  if (!is.data.frame(x)) {
    stop("Only data frames can be used to create a paged_table.")
  }

  class(x) <- c("paged_df", "data.frame")
  attr(x, "options") <- options
  x
}`

const rtdal006065Source0006 = `print.paged_df <- function(x, ...) {
  knitr::asis_output(
    paged_table_html(x, options = attr(x, "options")),
    meta = list(
      dependencies = html_dependency_pagedtable()
    )
  )
}`

