const rtdal006099Source0001 = `.onLoad <- function(lib, pkg) {
  .render_context <<- new_stack()
  if (getOption("rmarkdown.df_print", TRUE)) {
    registerMethods(list(
      # c(package, genname, class)
      c("knitr", "knit_print", "data.frame")
    ))
  }
}`

const rtdal006099Source0002 = `registerMethods <- function(methods) {
  lapply(methods, function(method) {
    pkg <- method[[1]]
    generic <- method[[2]]
    class <- method[[3]]
    func <- get(paste(generic, class, sep = "."))
    if (pkg %in% loadedNamespaces()) {
      registerS3method(generic, class, func, envir = asNamespace(pkg))
    }
    setHook(
      packageEvent(pkg, "onLoad"),
      function(...) {
        registerS3method(generic, class, func, envir = asNamespace(pkg))
      }
    )
  })
}`

