const rtdal006115Source0003 = `reset_accumulator <- function() {
  accumulated <<- data.frame(tag = c(), attribute = c(), value = c())
}`

const rtdal006115Source0004 = `html_accumulator <- function(tag, att, val, idx) {
  accumulated <<- rbind(accumulated, data.frame(
    tag = tag,
    attribute = att,
    value = val,
    stringsAsFactors = FALSE))
}`

const rtdal006115Source0005 = `test_that("different attribute quoting styles are supported", {
  call_resource_attrs(paste(
    "<img src='123'/>",
    "<img src=\"456\"/>"), html_accumulator)
  expect_equal(accumulated, data.frame(
    tag = c("img", "img"),
    attribute = c("src", "src"),
    value = c("123", "456"),
    stringsAsFactors = FALSE))
  reset_accumulator()
})`

const rtdal006115Source0006 = `test_that("irrelevant white space is ignored", {
  call_resource_attrs(paste(
    "<  img src =   \n",
    "        \t '123'\n",
    "        \t value ='abc'  />",
    "<link href=    '456'>"), html_accumulator)
  expect_equal(accumulated, data.frame(
    tag = c("img", "link"),
    attribute = c("src", "href"),
    value = c("123", "456"),
    stringsAsFactors = FALSE))
  reset_accumulator()
})`

const rtdal006115Source0007 = `test_that("common resource types are found in a simple document", {
  call_resource_attrs(paste(
    "<!DOCTYPE html>\n",
    "<HTML>\n",
    "<HEAD>\n",
    "  <SCRIPT SRC=\"foo.js\"></SCRIPT>\n",
    "  <LINK REL=\"stylesheet\" HREF=\"bar.css\"/>\n",
    "</HEAD>\n",
    "<BODY>\n",
    "  <IMG SRC=\"baz.png\"/>\n",
    "  <IFRAME SRC=\"quux.html\"/>\n",
    "</BODY>\n",
    "</HTML>\n"), html_accumulator)
  expect_equal(accumulated, data.frame(
    tag = c("script", "link", "img", "iframe"),
    attribute = c("src", "href", "src", "src"),
    value = c("foo.js", "bar.css", "baz.png", "quux.html"),
    stringsAsFactors = FALSE))
  reset_accumulator()
})`

const rtdal006115Source0008 = `test_that("resources referenced in CSS files are discovered", {
  call_css_resource_attrs(paste(
    "body {\n",
    "  background-image: url('foo.png');\n",
    "}\n",
    "p {\n",
    "  background-image: url(bar.png), url(\"baz.png\");\n",
    "}\n)"), html_accumulator)
  expect_equal(accumulated, data.frame(
    tag = c("css", "css", "css"),
    attribute = c("url", "url", "url"),
    value = c("foo.png", "bar.png", "baz.png"),
    stringsAsFactors = FALSE))
  reset_accumulator()
})`

