const rtdal006128Source0001 = "test_that(\"Metadata is available before pre_knit\", {\n  message_pre_knit = 'pre_knit handles metadata'\n  fmt <- md_document()\n  fmt$pre_knit <- function(input, ...) {\n    # `metadata` requires `rmarkdown::`-prefix. Otherwise, it becomes `list()`.\n    if (identical(rmarkdown::metadata, list(foo = 'bar'))) {\n      message(message_pre_knit)\n    }\n  }\n  input_file = tempfile(fileext = '.md')\n  writeLines('---\\nfoo: bar\\n---', input_file)\n  expect_message(render(input_file, fmt, quiet = TRUE), message_pre_knit)\n})"

const rtdal006128Source0002 = `test_that("file_scope split correctly input file", {
  skip_if_not(getRversion() >= '3.5')
  rmd <- local_rmd_file(c("# H1", "content1", "# H2", "content2"))
  file_scope_fun <- function(file) {
    x <- xfun::read_utf8(file)
    list(
      list(name = "A", content = x[1:2]),
      list(name = "B", content = x[3:4])
    )
  }
  splitted <- file_scope_split(rmd, file_scope_fun)
  expect_true(all(file.exists(splitted)))
  on.exit(unlink(splitted), add = TRUE, after = FALSE)
  expect_match(splitted, "[.]split[.]md$")
  expect_snapshot_file(splitted[1])
  expect_snapshot_file(splitted[2])
})`

const rtdal006128Source0003 = `test_that("Input file is not corrupted", {
  input <- tempfile()
  on.exit(unlink(input), add = TRUE, after = FALSE)
  saveRDS("test", input)
  # try() is necessary for Pandoc <= 2.14.2
  try(render(input, quiet = TRUE))
  expect_equal(readRDS(input), "test")
})`

