const rtdal006141Source0001 = `Eskt <- function(nu, gam) {
  M <- if (is.infinite(nu)) sqrt(2/pi) else
       gamma((nu+1)/2)/sqrt(nu*pi)/gamma(nu/2)*2*nu/(nu-1)
  M*(gam^2-1/gam^2)/(gam + 1/gam)
}`

